import { useState, useEffect, useCallback } from 'react'
import { Link } from 'react-router-dom'
import { FaChevronLeft, FaChevronRight } from 'react-icons/fa'
import styles from './Carousel.module.css'

function Carousel({ slides }) {
    const [currentIndex, setCurrentIndex] = useState(0)
    const [isPaused, setIsPaused] = useState(false)
    const [isMobile, setIsMobile] = useState(window.innerWidth <= 768)

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768)
        }
        window.addEventListener('resize', handleResize)
        // Check on mount to be sure
        handleResize()
        return () => window.removeEventListener('resize', handleResize)
    }, [])

    const nextSlide = useCallback(() => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % slides.length)
    }, [slides.length])

    const prevSlide = () => {
        setCurrentIndex((prevIndex) => (prevIndex - 1 + slides.length) % slides.length)
    }

    const goToSlide = (index) => {
        setCurrentIndex(index)
    }

    useEffect(() => {
        if (!isPaused) {
            const interval = setInterval(nextSlide, 5000)
            return () => clearInterval(interval)
        }
    }, [isPaused, nextSlide])

    if (!slides || slides.length === 0) {
        return null
    }

    return (
        <div
            className={styles.carousel_container}
            onMouseEnter={() => setIsPaused(true)}
            onMouseLeave={() => setIsPaused(false)}
        >
            {slides.map((slide, index) => (
                <div
                    key={index}
                    className={`${styles.slide} ${index === currentIndex ? styles.active : ''}`}
                    style={{ backgroundImage: `url(${isMobile && slide.mobileImage ? slide.mobileImage : slide.image})` }}
                >

                    {(slide.title || slide.text || slide.buttonText) && (
                        <>
                            <div className={styles.slide_overlay}></div>
                            <div className={styles.slide_content}>
                                {slide.title && <h2 className={styles.slide_title}>{slide.title}</h2>}
                                {slide.text && <p className={styles.slide_text}>{slide.text}</p>}
                                {slide.buttonText && (
                                    slide.linkIsScroll ? (
                                        <button onClick={slide.action} className={styles.slide_button}>
                                            {slide.buttonText}
                                        </button>
                                    ) : (
                                        <Link to={slide.link} className={styles.slide_button}>
                                            {slide.buttonText}
                                        </Link>
                                    )
                                )}
                            </div>
                        </>
                    )}
                </div>
            ))}

            <button className={`${styles.arrow} ${styles.arrow_left}`} onClick={prevSlide} aria-label="Anterior">
                <FaChevronLeft />
            </button>
            <button className={`${styles.arrow} ${styles.arrow_right}`} onClick={nextSlide} aria-label="Próximo">
                <FaChevronRight />
            </button>

            <div className={styles.indicators}>
                {slides.map((_, index) => (
                    <button
                        key={index}
                        className={`${styles.indicator} ${index === currentIndex ? styles.active : ''}`}
                        onClick={() => goToSlide(index)}
                        aria-label={`Ir para slide ${index + 1}`}
                    />
                ))}
            </div>
        </div>
    )
}

export default Carousel
