import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useState, useEffect } from 'react'
import { useCallback } from 'react'

import styles from './MyAdoptions.module.css'

import RoundedImage from '../../layout/RoundedImage'

function MyAdoptions() {
  const [pets, setPets] = useState([])
  const [token] = useState(localStorage.getItem('token') || '')

  // função para carregar adoções
  const loadAdoptions = useCallback(async () => {
    if (!token) {
      setPets([])
      return
    }

    try {
      const response = await api.get('/pets/myadoptions', {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`,
        },
      })

      const unsortedPets = response.data.pets || []

      // Ordenação inteligente:
      // 1. Pets disponíveis (em andamento) vêm primeiro.
      // 2. Entre os disponíveis, os que possuem mensagem do administrador vêm antes.
      // 3. Dentro desses grupos, os mais recentemente atualizados vêm primeiro.
      // 4. Pets já adotados (concluídos) ficam sempre no final.
      const sortedPets = unsortedPets.sort((a, b) => {
        // Se um está disponível e o outro não
        if (a.available && !b.available) return -1
        if (!a.available && b.available) return 1

        // Se ambos estão disponíveis
        if (a.available && b.available) {
          const aHasMsg = !!a.adopter?.adminMessage
          const bHasMsg = !!b.adopter?.adminMessage

          if (aHasMsg && !bHasMsg) return -1
          if (!aHasMsg && bHasMsg) return 1

          // Se ambos têm ou ambos não têm mensagem, ordena por data
          const dateA = new Date(a.adopter?.updatedAt || a.updatedAt)
          const dateB = new Date(b.adopter?.updatedAt || b.updatedAt)
          return dateB - dateA
        }

        // Se ambos não estão disponíveis (concluídos), ordena por data
        const dateA = new Date(a.adopter?.updatedAt || a.updatedAt)
        const dateB = new Date(b.adopter?.updatedAt || b.updatedAt)
        return dateB - dateA
      })

      setPets(sortedPets)
    } catch (err) {
      setPets([])
    }
  }, [token])

  useEffect(() => {
    loadAdoptions()

    const interval = setInterval(() => {
      loadAdoptions()
    }, 5000)

    return () => clearInterval(interval)
  }, [loadAdoptions])

  return (
    <section>
      <div className={styles.petlist_header}>
        <h1>Minhas Adoções</h1>
      </div>

      <div className={styles.petlist_container}>
        {pets.length > 0 &&
          pets.map((pet) => (
            <div className={styles.petlist_row} key={pet._id}>
              {pet.images && pet.images.length > 0 && pet.images[0] ? (
                <RoundedImage
                  src={`${getApiBase()}/images/pets/${pet.images[0]}`}
                  alt={pet.name}
                  width="px75"
                />
              ) : null}

              <span className={styles.pet_name}>{pet.name}</span>

              <div className={styles.donor_info}>
                <h4 className={styles.donor_title}>
                  <span className={styles.icon}>👤</span> Informações do Doador
                </h4>
                <div className={styles.donor_details}>
                  <div className={styles.info_item}>
                    <span className={styles.info_label}>Fale com:</span>
                    <span className={styles.info_value}>{pet.user.name}</span>
                  </div>
                  <div className={styles.info_item}>
                    <span className={styles.info_label}>Ligue para:</span>
                    <span className={styles.info_value}>{pet.user.phone}</span>
                  </div>
                </div>
              </div>

              <div className={styles.actions}>
                {pet.available ? (
                  <>
                    <p className={styles.status_badge} style={{
                      borderColor: pet.adopter?.status === 'Aprovado' ? '#749666' :
                        pet.adopter?.status === 'Recusado' ? '#f44336' :
                          pet.adopter?.status === 'Em análise' ? '#ffb583' : '#749666',
                      background: pet.adopter?.status === 'Aprovado' ? '#e8f5e9' : 'white'
                    }}>
                      {pet.adopter?.status === 'Pendente' && '✅ Solicitação enviada!'}
                      {pet.adopter?.status === 'Em análise' && '⏳ Em análise'}
                      {pet.adopter?.status === 'Aprovado' && '🎉 Solicitação aprovada!'}
                      {pet.adopter?.status === 'Recusado' && '❌ Não aprovada'}
                    </p>

                    {pet.adopter?.adminMessage && (
                      <div className={styles.admin_message_box}>
                        <div className={styles.message_header}>
                          <span className={styles.icon}>✉️</span>
                          <strong>Recado do Doador/SAMA:</strong>
                        </div>
                        <p className={styles.message_text}>{pet.adopter.adminMessage}</p>
                      </div>
                    )}
                  </>
                ) : (
                  <p className={styles.status_finalizado}>
                    🏁 Adoção concluída com sucesso!
                  </p>
                )}
              </div>
            </div>
          ))}

        {pets.length === 0 && (
          <p style={{ textAlign: 'center', marginTop: '2em', opacity: 0.6 }}>
            🐾 Ainda não há adoções de Pets.
          </p>
        )}
      </div>
    </section>
  )
}

export default MyAdoptions
