import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'
import { useLocation } from 'react-router-dom'
import React, { useState, useEffect, useMemo } from 'react'
import styles from './AdoptionHome.module.css'
import { FaPaw, FaCat, FaDog } from 'react-icons/fa'
import PetModal from '../../layout/PetModal'

function AdoptionHome() {
    const [pets, setPets] = useState([])
    const [visibleDogsCount, setVisibleDogsCount] = useState(12) // 3 rows of 4
    const [visibleCatsCount, setVisibleCatsCount] = useState(12) // 3 rows of 4
    const [visibleOthersCount, setVisibleOthersCount] = useState(12) // 3 rows of 4
    const [selectedPet, setSelectedPet] = useState(null)

    const [loading, setLoading] = useState(true)

    // Estados dos Filtros
    const [filters, setFilters] = useState({
        type: '',
        gender: '',
        size: '',
        color: '',
        age: '',
        sort: 'Mais recentes'
    })

    const [tempFilters, setTempFilters] = useState({
        type: '',
        gender: '',
        size: '',
        color: '',
        age: '',
        instituteId: ''
    })

    const location = useLocation()

    const [institutes, setInstitutes] = useState([])


    useEffect(() => {
        setLoading(true)
        api.get('/pets').then((response) => {
            const allPets = response.data.pets || []
            setPets(allPets)
            setLoading(false)
        }).catch((error) => {
            console.error('Erro ao buscar pets:', error)
            setPets([])
            setLoading(false)
        })

        // Fetch institutes
        api.get('/users/institutes').then((response) => {
            setInstitutes(response.data.institutes || [])
        }).catch((error) => {
            console.error('Erro ao buscar institutos:', error)
        })
    }, [location.search])


    // Filter Logic using useMemo for immediate calculation
    const filteredPets = useMemo(() => {
        if (!pets) return []

        const params = new URLSearchParams(location.search)
        const searchParam = params.get('search')?.toLowerCase()

        let result = pets.filter(pet => pet.available !== false)

        if (searchParam) {
            result = result.filter(pet =>
                pet.name?.toLowerCase().includes(searchParam) ||
                pet.breed?.toLowerCase().includes(searchParam) ||
                pet.type?.toLowerCase().includes(searchParam)
            )
        }

        if (filters.type) {
            result = result.filter(pet => pet.type?.toLowerCase() === filters.type.toLowerCase())
        }
        if (filters.gender) {
            result = result.filter(pet => pet.gender === filters.gender)
        }
        if (filters.age) {
            result = result.filter(pet => {
                const ageString = String(pet.age).toLowerCase()
                const value = parseInt(ageString)

                if (isNaN(value)) return false

                let ageInMonths = 0
                if (ageString.includes('mes') || ageString.includes('mês')) {
                    ageInMonths = value
                } else {
                    // Assume years
                    ageInMonths = value * 12
                }

                if (filters.age === 'Filhote') return ageInMonths <= 12
                if (filters.age === 'Jovem') return ageInMonths > 12 && ageInMonths <= 36
                if (filters.age === 'Adulto') return ageInMonths > 36 && ageInMonths <= 96
                if (filters.age === 'Senior') return ageInMonths > 96
                return true
            })
        }

        if (filters.size) {
            result = result.filter(pet => {
                const weight = pet.weight || 0
                if (filters.size === 'Pequeno') return pet.size === 'Pequeno' || weight < 10
                if (filters.size === 'Médio') return pet.size === 'Médio' || (weight >= 10 && weight <= 25)
                if (filters.size === 'Grande') return pet.size === 'Grande' || weight > 25
                return true
            })
        }

        if (filters.color) {
            result = result.filter(pet => pet.color === filters.color)
        }

        if (filters.instituteId) {
            result = result.filter(pet => String(pet.user?._id) === String(filters.instituteId))
        }

        // Sorting
        if (filters.sort === 'Alfabetica') {
            result.sort((a, b) => a.name.localeCompare(b.name))
        } else if (filters.sort === 'Mais recentes') {
            result.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
        } else if (filters.sort === 'Mais antigos') {
            result.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
        }

        return result
    }, [pets, filters, location.search])

    const dogs = useMemo(() => filteredPets.filter(pet => pet.type?.toLowerCase() === 'cachorro'), [filteredPets])
    const cats = useMemo(() => filteredPets.filter(pet => pet.type?.toLowerCase() === 'gato'), [filteredPets])
    const others = useMemo(() => filteredPets.filter(pet => {
        const type = pet.type?.toLowerCase()
        return type !== 'cachorro' && type !== 'gato'
    }), [filteredPets])
    const handleFilterChange = (e) => {
        const { name, value } = e.target
        setTempFilters({ ...tempFilters, [name]: value })
    }

    const applyFilters = () => {
        setFilters({ ...filters, ...tempFilters })
    }


    return (
        <section className={styles.adoption_home_section}>
            <div className={styles.paw_background}>
                <FaPaw className={`${styles.decor_icon} ${styles.pos_1}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_2}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_3}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_4}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_5}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_6}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_7}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_8}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_9}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_10}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_11}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_12}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_13}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_14}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_15}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_16}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_17}`} />
                <FaDog className={`${styles.decor_icon} ${styles.pos_18}`} />
                <FaPaw className={`${styles.decor_icon} ${styles.pos_19}`} />
                <FaCat className={`${styles.decor_icon} ${styles.pos_20}`} />
            </div>
            <div className={styles.header_container}>
                <div className={styles.breadcrumbs}>Home / Quero adotar</div>
                <h1 className={styles.page_title}>Encontre seu novo amigo</h1>
                <p className={styles.page_subtitle}>
                    Confira abaixo os <strong>{pets.filter(p => p.available !== false).length}</strong> pets disponíveis para adoção responsável
                </p>

                {!loading && (
                    <div className={styles.stats_container}>
                        <div className={styles.stat_card}>
                            <div className={styles.stat_icon_box} style={{ backgroundColor: '#fff' }}>
                                <FaPaw style={{ color: '#446042' }} />
                            </div>
                            <div className={styles.stat_info}>
                                <span className={styles.stat_value}>{pets.filter(p => p.available !== false).length}</span>
                                <span className={styles.stat_label}>Total Disponível</span>
                            </div>
                        </div>
                        <div className={styles.stat_card}>
                            <div className={styles.stat_icon_box} style={{ backgroundColor: '#fff' }}>
                                <FaDog style={{ color: '#446042' }} />
                            </div>
                            <div className={styles.stat_info}>
                                <span className={styles.stat_value}>{pets.filter(p => p.available !== false && p.type?.toLowerCase() === 'cachorro').length}</span>
                                <span className={styles.stat_label}>Cães</span>
                            </div>
                        </div>
                        <div className={styles.stat_card}>
                            <div className={styles.stat_icon_box} style={{ backgroundColor: '#fff' }}>
                                <FaCat style={{ color: '#446042' }} />
                            </div>
                            <div className={styles.stat_info}>
                                <span className={styles.stat_value}>{pets.filter(p => p.available !== false && p.type?.toLowerCase() === 'gato').length}</span>
                                <span className={styles.stat_label}>Felinos</span>
                            </div>
                        </div>
                        <div className={styles.stat_card}>
                            <div className={styles.stat_icon_box} style={{ backgroundColor: '#fff' }}>
                                <FaPaw style={{ color: '#446042', transform: 'rotate(20deg)' }} />
                            </div>
                            <div className={styles.stat_info}>
                                <span className={styles.stat_value}>{pets.filter(p => p.available !== false && p.type?.toLowerCase() !== 'cachorro' && p.type?.toLowerCase() !== 'gato').length}</span>
                                <span className={styles.stat_label}>Outros</span>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Horizontal Filter Bar */}
            <div className={styles.filter_bar_container}>
                <div className={styles.filter_group_row}>
                    <div className={styles.filter_inputs_wrapper}>
                        <select name="type" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.type}>
                            <option value="">Todas as espécies</option>
                            <option value="Cachorro">Cães</option>
                            <option value="Gato">Felinos</option>
                            <option value="Outros">Outros</option>
                        </select>

                        <select name="gender" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.gender}>
                            <option value="">Todos os sexos</option>
                            <option value="Macho">Macho</option>
                            <option value="Fêmea">Fêmea</option>
                        </select>

                        <select name="size" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.size}>
                            <option value="">Todos os portes</option>
                            <option value="Pequeno">Pequeno</option>
                            <option value="Médio">Médio</option>
                            <option value="Grande">Grande</option>
                        </select>

                        <select name="color" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.color}>
                            <option value="">Todas as cores</option>
                            {[...new Set(pets.map(p => p.color).filter(c => c))].map(color => (
                                <option key={color} value={color}>{color}</option>
                            ))}
                        </select>

                        <select name="age" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.age}>
                            <option value="">Todas as idades</option>
                            <option value="Filhote">Filhote (até 1 ano)</option>
                            <option value="Jovem">Jovem (1-3 anos)</option>
                            <option value="Adulto">Adulto (3-8 anos)</option>
                            <option value="Senior">Sênior (acima de 8 anos)</option>
                        </select>

                        <select name="instituteId" className={styles.filter_select} onChange={handleFilterChange} value={tempFilters.instituteId}>
                            <option value="">Todas as ONGs / Institutos</option>
                            {institutes.map(inst => (
                                <option key={inst._id} value={inst._id}>{inst.instituteName || inst.name}</option>
                            ))}
                        </select>
                    </div>

                    <button className={styles.search_button} onClick={applyFilters}>
                        Buscar
                    </button>
                </div>
            </div>

            {/* Sorting Links */}
            <div className={styles.sorting_container}>
                <span
                    className={`${styles.sort_link} ${filters.sort === 'Mais recentes' ? styles.active : ''}`}
                    onClick={() => setFilters({ ...filters, sort: 'Mais recentes' })}
                >Mais recentes</span>

                <span
                    className={`${styles.sort_link} ${filters.sort === 'Mais antigos' ? styles.active : ''}`}
                    onClick={() => setFilters({ ...filters, sort: 'Mais antigos' })}
                >Mais antigos</span>

                <span
                    className={`${styles.sort_link} ${filters.sort === 'Alfabetica' ? styles.active : ''}`}
                    onClick={() => setFilters({ ...filters, sort: 'Alfabetica' })}
                >A-Z</span>

                {/* Views not implemented in backend yet */}
                <span className={styles.sort_link}>Mais vistos</span>
                <span className={styles.sort_link}>Menos vistos</span>
            </div>

            {/* Empty State */}
            {!loading && dogs.length === 0 && cats.length === 0 && others.length === 0 && (
                <div style={{ textAlign: 'center', padding: '4em 2em', color: '#666' }}>
                    <FaPaw size={50} style={{ opacity: 0.2, marginBottom: '20px' }} />
                    <h2>Nenhum pet encontrado</h2>
                    <p>No momento não temos animais que correspondam aos seus filtros.</p>
                </div>
            )}

            {/* Dogs Grid */}
            {dogs.length > 0 && (
                <>
                    <div className={styles.section_title_container}>
                        <h2>Cães</h2>
                        <div className={styles.section_divider}></div>
                    </div>

                    <div className={styles.pet_container}>
                        {dogs.slice(0, visibleDogsCount).map((pet) => (
                            <div key={pet._id} className={styles.pet_card}>
                                {pet.images && pet.images.length > 0 && pet.images[0] ? (
                                    <div
                                        style={{
                                            backgroundImage: `url(${getApiBase()}/images/pets/${pet.images[0]})`
                                        }}
                                        className={styles.pet_card_image}>
                                    </div>
                                ) : (
                                    <div
                                        style={{
                                            backgroundColor: '#e0e0e0',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            color: '#000',
                                            height: '250px',
                                            fontFamily: "'Rubik', sans-serif"
                                        }}
                                        className={styles.pet_card_image}>
                                        <span>Sem imagem</span>
                                    </div>
                                )}
                                <div className={styles.pet_card_content}>
                                    <h3>{pet.name}</h3>
                                    <div className={styles.pet_info_container}>
                                        <p className={styles.pet_info}><strong>Peso:</strong> {pet.weight}kg</p>
                                        <p className={styles.pet_info}><strong>Idade:</strong> {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} anos`}</p>
                                        <p className={styles.pet_info}><strong>Gênero:</strong> {pet.gender}</p>
                                        <p className={styles.pet_info}><strong>Cor:</strong> {pet.color}</p>
                                    </div>

                                    <button
                                        onClick={() => setSelectedPet(pet)}
                                        className={styles.adopt_button}
                                    >
                                        Adotar
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    {visibleDogsCount < dogs.length && (
                        <div style={{ textAlign: 'center', marginTop: '2em', marginBottom: '4em' }}>
                            <button
                                onClick={() => setVisibleDogsCount(dogs.length)}
                                style={{
                                    padding: '12px 30px',
                                    backgroundColor: 'white',
                                    border: '1px solid #446042',
                                    color: '#446042',
                                    borderRadius: '30px',
                                    cursor: 'pointer',
                                    fontSize: '1em',
                                    fontWeight: 'bold'
                                }}
                            >
                                Ver todos
                            </button>
                        </div>
                    )}
                </>
            )}

            {/* Cats Grid */}
            {cats.length > 0 && (
                <>
                    <div className={styles.section_title_container}>
                        <h2>Felinos</h2>
                        <div className={styles.section_divider}></div>
                    </div>

                    <div className={styles.pet_container}>
                        {cats.slice(0, visibleCatsCount).map((pet) => (
                            <div key={pet._id} className={styles.pet_card}>
                                {pet.images && pet.images.length > 0 && pet.images[0] ? (
                                    <div
                                        style={{
                                            backgroundImage: `url(${getApiBase()}/images/pets/${pet.images[0]})`
                                        }}
                                        className={styles.pet_card_image}>
                                    </div>
                                ) : (
                                    <div
                                        style={{
                                            backgroundColor: '#e0e0e0',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            color: '#000',
                                            height: '250px',
                                            fontFamily: "'Rubik', sans-serif"
                                        }}
                                        className={styles.pet_card_image}>
                                        <span>Sem imagem</span>
                                    </div>
                                )}
                                <div className={styles.pet_card_content}>
                                    <h3>{pet.name}</h3>
                                    <div className={styles.pet_info_container}>
                                        <p className={styles.pet_info}><strong>Peso:</strong> {pet.weight}kg</p>
                                        <p className={styles.pet_info}><strong>Idade:</strong> {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} anos`}</p>
                                        <p className={styles.pet_info}><strong>Gênero:</strong> {pet.gender}</p>
                                        <p className={styles.pet_info}><strong>Cor:</strong> {pet.color}</p>
                                    </div>

                                    <button
                                        onClick={() => setSelectedPet(pet)}
                                        className={styles.adopt_button}
                                    >
                                        Adotar
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    {visibleCatsCount < cats.length && (
                        <div style={{ textAlign: 'center', marginTop: '2em' }}>
                            <button
                                onClick={() => setVisibleCatsCount(cats.length)}
                                style={{
                                    padding: '12px 30px',
                                    backgroundColor: 'white',
                                    border: '1px solid #446042',
                                    color: '#446042',
                                    borderRadius: '30px',
                                    cursor: 'pointer',
                                    fontSize: '1em',
                                    fontWeight: 'bold'
                                }}
                            >
                                Ver todos
                            </button>
                        </div>
                    )}
                </>
            )}
            {/* Others Grid */}
            {others.length > 0 && (
                <>
                    <div className={styles.section_title_container}>
                        <h2>Outros Pets</h2>
                        <div className={styles.section_divider}></div>
                    </div>

                    <div className={styles.pet_container}>
                        {others.slice(0, visibleOthersCount).map((pet) => (
                            <div key={pet._id} className={styles.pet_card}>
                                {pet.images && pet.images.length > 0 && pet.images[0] ? (
                                    <div
                                        style={{
                                            backgroundImage: `url(${getApiBase()}/images/pets/${pet.images[0]})`
                                        }}
                                        className={styles.pet_card_image}>
                                    </div>
                                ) : (
                                    <div
                                        style={{
                                            backgroundColor: '#e0e0e0',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            color: '#000',
                                            height: '250px',
                                            fontFamily: "'Rubik', sans-serif"
                                        }}
                                        className={styles.pet_card_image}>
                                        <span>Sem imagem</span>
                                    </div>
                                )}
                                <div className={styles.pet_card_content}>
                                    <h3>{pet.name}</h3>
                                    <div className={styles.pet_info_container}>
                                        <p className={styles.pet_info}><strong>Peso:</strong> {pet.weight}kg</p>
                                        <p className={styles.pet_info}><strong>Idade:</strong> {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} anos`}</p>
                                        <p className={styles.pet_info}><strong>Gênero:</strong> {pet.gender}</p>
                                        <p className={styles.pet_info}><strong>Cor:</strong> {pet.color}</p>
                                    </div>

                                    <button
                                        onClick={() => setSelectedPet(pet)}
                                        className={styles.adopt_button}
                                    >
                                        Adotar
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    {visibleOthersCount < others.length && (
                        <div style={{ textAlign: 'center', marginTop: '2em', marginBottom: '4em' }}>
                            <button
                                onClick={() => setVisibleOthersCount(others.length)}
                                style={{
                                    padding: '12px 30px',
                                    backgroundColor: 'white',
                                    border: '1px solid #446042',
                                    color: '#446042',
                                    borderRadius: '30px',
                                    cursor: 'pointer',
                                    fontSize: '1em',
                                    fontWeight: 'bold'
                                }}
                            >
                                Ver todos
                            </button>
                        </div>
                    )}
                </>
            )}

            {/* Modal */}
            {selectedPet && (
                <PetModal pet={selectedPet} onClose={() => setSelectedPet(null)} />
            )}
        </section>
    )
}

export default AdoptionHome
