import { useContext, useState } from 'react'
import { Link, useLocation } from 'react-router-dom'
import styles from './Navbar.module.css'
import Logo from '../../assets/img/seloSama.png'
import { FaBars, FaTimes, FaWhatsapp, FaFacebook, FaInstagram, FaPhoneAlt, FaChevronDown, FaUserCircle } from 'react-icons/fa'

/* context */
import { Context } from '../../context/UserContext'

function Navbar() {

  const { authenticated, user, logout } = useContext(Context)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const location = useLocation()

  // Determine if it's a tree-related page
  const isTreePage = location.pathname.startsWith('/arvore') ||
    location.pathname.startsWith('/arvores') ||
    location.pathname === '/sama'

  // Dropdown list items
  const institucionalItems = [
    { label: 'Sobre o GarçaPet', link: '/sobre' },
    { label: 'Castração', link: '/castracao' },
    { label: 'Conheça a SAMA', link: '/sama' },
    { label: 'Zoológico', link: '/zoologico' }
  ]

  const termosItems = [
    { label: 'Funcionamento da plataforma', link: '/funcionalidade' }
  ]

  return (
    <header className={styles.header_container}>
      {/* Top Bar */}
      <div className={styles.top_bar}>
        <div className={styles.top_bar_contact}>
          <FaPhoneAlt className={styles.contact_icon} />
          <span>Tel: (14) 3407-6600</span>
        </div>
        <div className={styles.top_bar_socials}>
          <a href="https://wa.me/551434076600" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp" className={styles.social_link}>
            <FaWhatsapp />
          </a>
          <a href="https://www.facebook.com/share/1DGJSqP8i5/" target="_blank" rel="noopener noreferrer" aria-label="Facebook" className={styles.social_link}>
            <FaFacebook />
          </a>
          <a href="https://www.instagram.com/semitgarca?igsh=MXN1MWtqdm55ajNhNw==" target="_blank" rel="noopener noreferrer" aria-label="Instagram" className={styles.social_link}>
            <FaInstagram />
          </a>
        </div>
      </div>

      <nav className={styles.navbar}>
        {/* Logo e nome */}
        <Link to="/" className={styles.navbar_logo} onClick={() => setMobileMenuOpen(false)} translate="no">
          <img src={Logo} alt="Logo" className={styles.navbar_logo_img} />
          {isTreePage ? (
            <h2 className={styles.tree_brand}>
              <span className={styles.tree_first_letter}>S</span>
              <span className={styles.tree_rest_letters}>ama</span>
            </h2>
          ) : (
            <h2 className={styles.pet_brand}>
              <span className={styles.garca_text}>Garça</span>
              <span className={styles.pet_text}>Pet</span>
            </h2>
          )}
        </Link>

        {/* Botão hambúrguer para mobile */}
        <button
          className={styles.mobile_menu_button}
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Menu"
        >
          {mobileMenuOpen ? <FaTimes /> : <FaBars />}
        </button>

        {/* Links */}
        <ul className={`${styles.navbar_links} ${mobileMenuOpen ? styles.mobile_menu_open : ''}`}>

          {/* Institucional Dropdown */}
          <li className={styles.dropdown}>
            <div className={styles.dropdown_toggle}>
              Institucional <FaChevronDown size={12} />
            </div>
            <div className={styles.dropdown_menu}>
              {institucionalItems.map((item, index) => (
                <Link key={index} to={item.link} className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)} translate="no">
                  {item.label}
                </Link>
              ))}
            </div>
          </li>

          {/* Termos Dropdown */}
          <li className={styles.dropdown}>
            <div className={styles.dropdown_toggle}>
              Termos <FaChevronDown size={12} />
            </div>
            <div className={styles.dropdown_menu}>
              {termosItems.map((item, index) => (
                <Link key={index} to={item.link} className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>
                  {item.label}
                </Link>
              ))}
            </div>
          </li>

          {/* Adoção Dropdown containing Denounce */}
          <li className={styles.dropdown}>
            <Link to="/" className={styles.dropdown_toggle} onClick={() => setMobileMenuOpen(false)}>
              Adoção <FaChevronDown size={12} />
            </Link>
            <div className={styles.dropdown_menu}>
              <Link to="/" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Quero Adotar</Link>
              <Link to="/denunciar" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Denuncie</Link>
            </div>
          </li>

          {authenticated ? (
            <>
              {/* SAMA Admin Dropdown - Institutional Management */}
              {/* standard menus for everyone (including admin for their own pets/trees) */}
              <li className={styles.dropdown}>
                <div className={styles.dropdown_toggle}>
                  Árvores <FaChevronDown size={12} />
                </div>
                <div className={styles.dropdown_menu}>
                  {!user?.isAdmin && !user?.canManageTrees && (
                    <>
                      <Link to="/arvores" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Solicitar Muda</Link>
                      <Link to="/arvore/myrequests" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Minhas Solicitações</Link>
                    </>
                  )}
                  {(user?.isAdmin || user?.canManageTrees) && (
                    <>
                      <Link to="/arvores" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Catálogo de Árvores</Link>
                      <Link to="/arvore/add" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Cadastrar Muda</Link>
                      <Link to="/arvore/myarvore" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Gestão de Mudas</Link>
                      {user?.canManageTrees && !user?.isAdmin && (
                        <Link to="/arvore/myrequests" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Minhas Solicitações</Link>
                      )}
                    </>
                  )}
                </div>
              </li>

              <li className={styles.dropdown}>
                <div className={styles.dropdown_toggle}>
                  Pets <FaChevronDown size={12} />
                </div>
                <div className={styles.dropdown_menu}>
                  <Link to="/pet/mypets" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Meus Pets</Link>
                  <Link to="/pet/myadoptions" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Minhas Adoções</Link>
                  {user?.isAdmin && <Link to="/pet/add" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Cadastrar Pet SAMA</Link>}
                </div>
              </li>

              {/* User Profile Dropdown */}
              <li className={`${styles.dropdown} ${styles.user_dropdown}`}>
                <div className={styles.dropdown_toggle}>
                  <FaUserCircle size={24} /> <FaChevronDown size={10} style={{ marginLeft: 5 }} />
                </div>
                <div className={styles.dropdown_menu}>
                  {user?.isAdmin && (
                    <Link to="/admin/users" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Gestão de Usuários</Link>
                  )}
                  <Link to="/user/profile" className={styles.dropdown_item} onClick={() => setMobileMenuOpen(false)}>Meu Perfil</Link>
                  <span className={styles.dropdown_item} onClick={() => { logout(); setMobileMenuOpen(false); }}>Sair</span>
                </div>
              </li>
            </>
          ) : (
            <>
              <li>
                <Link to="/arvores" onClick={() => setMobileMenuOpen(false)}>Árvores</Link>
              </li>
              <li className={styles.navbar_btn_container}>
                <Link to="/login" className={`${styles.navbar_button} ${styles.login_button}`} onClick={() => setMobileMenuOpen(false)}>Entrar</Link>
              </li>
              <li className={styles.navbar_btn_container}>
                <Link to="/register" className={`${styles.navbar_button} ${styles.register_button}`} onClick={() => setMobileMenuOpen(false)}>Cadastrar</Link>
              </li>
            </>
          )}

        </ul>
      </nav>
    </header>
  )
}

export default Navbar
