import { useState, useEffect, useRef } from 'react'
import styles from './Sama.module.css'

import bugiosImg from '../../../assets/img/bugios.jpeg'
import capaSama from '../../../assets/img/capasama.png'
import { FaTree, FaSearch, FaChevronLeft, FaChevronRight, FaPhoneAlt, FaLeaf } from 'react-icons/fa'
import { speciesImages } from '../../../utils/treeImageMapper'

// Research Animals
import img18 from '../../../assets/img/zoologico/sama/img18.jpeg'
import img19 from '../../../assets/img/zoologico/sama/img19.jpeg'
import img20 from '../../../assets/img/zoologico/sama/img20.jpeg'
import img21 from '../../../assets/img/zoologico/sama/img21.jpeg'
import img22 from '../../../assets/img/zoologico/sama/img22.jpeg'
import img23 from '../../../assets/img/zoologico/sama/img23.jpeg'
import img24 from '../../../assets/img/zoologico/sama/img24.jpeg'
import img25 from '../../../assets/img/zoologico/sama/img25.jpeg'
import img26 from '../../../assets/img/zoologico/sama/img26.jpeg'
import secretariaImg from '../../../assets/img/zoologico/sama/secretaria.jpeg'


function Sama() {
    // Carousel State
    const [currentAnimalSlide, setCurrentAnimalSlide] = useState(0);
    const researchAnimals = [
        bugiosImg, img18, img19, img20, img21, img22, img23, img24, img25, img26
    ];
    const [animalsPerView, setAnimalsPerView] = useState(4);

    // Drag & Swipe Logic
    const [isDragging, setIsDragging] = useState(false);
    const [startX, setStartX] = useState(0);
    const [dragOffset, setDragOffset] = useState(0);
    const carouselTrackRef = useRef(null);

    // Update items per view based on window width
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth <= 768) {
                setAnimalsPerView(1);
            } else if (window.innerWidth <= 1024) {
                setAnimalsPerView(2);
            } else {
                setAnimalsPerView(4);
            }
        };

        handleResize(); // Initial call
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const nextAnimalSlide = () => {
        const maxSlide = Math.max(0, researchAnimals.length - animalsPerView);
        setCurrentAnimalSlide(prev => (prev < maxSlide ? prev + 1 : 0));
    };

    const prevAnimalSlide = () => {
        const maxSlide = Math.max(0, researchAnimals.length - animalsPerView);
        setCurrentAnimalSlide(prev => (prev > 0 ? prev - 1 : maxSlide));
    };

    // Auto-advance logic
    useEffect(() => {
        if (isDragging) return;
        const interval = setInterval(() => {
            const maxSlide = Math.max(0, researchAnimals.length - animalsPerView);
            if (maxSlide > 0) {
                setCurrentAnimalSlide((prev) => (prev < maxSlide ? prev + 1 : 0));
            }
        }, 3000);
        return () => clearInterval(interval);
    }, [researchAnimals.length, isDragging, animalsPerView]);

    // Drag handlers
    const handleMouseDown = (e) => {
        setIsDragging(true);
        setStartX(e.pageX);
        setDragOffset(0);
    };

    const handleMouseMove = (e) => {
        if (!isDragging) return;
        e.preventDefault();
        const x = e.pageX;
        const walk = (x - startX);
        setDragOffset(walk);
    };

    const handleMouseUp = () => {
        if (!isDragging) return;
        setIsDragging(false);

        if (carouselTrackRef.current) {
            const trackWidth = carouselTrackRef.current.offsetWidth;
            const itemWidth = trackWidth / animalsPerView;
            const movedSlides = Math.round(dragOffset / itemWidth);
            let newSlide = currentAnimalSlide - movedSlides;

            const maxSlide = Math.max(0, researchAnimals.length - animalsPerView);
            newSlide = Math.max(0, Math.min(newSlide, maxSlide));
            setCurrentAnimalSlide(newSlide);
        }
        setDragOffset(0);
    };

    const handleMouseLeave = () => {
        if (isDragging) handleMouseUp();
    };

    const handleTouchStart = (e) => {
        setIsDragging(true);
        setStartX(e.touches[0].pageX);
        setDragOffset(0);
    };

    const handleTouchMove = (e) => {
        if (!isDragging) return;
        const x = e.touches[0].pageX;
        const walk = (x - startX);
        setDragOffset(walk);
    };

    useEffect(() => {
        window.scrollTo(0, 0);
    }, []);

    const speciesData = [
        { name: "Coração de negro", img: speciesImages["Coração de Negro"], desc: "Porte médio, ideal para sombreamento." },
        { name: "Resedá gigante", img: speciesImages["Resedá"], desc: "Floração roxa vibrante e crescimento rápido." },
        { name: "Ipê branco", img: speciesImages["Ipê Branco"], desc: "A beleza clássica da floração branca brasileira." },
        { name: "Ipê amarelo", img: speciesImages["Ipê Amarelo"], desc: "O símbolo do Brasil com suas flores douradas." },
        { name: "Jacarandá", img: speciesImages["Jacarandá"], desc: "Folhagem delicada e flores purpúreas." },
        { name: "Sabão de soldado", img: speciesImages["Sabão Soldado"], desc: "Resistente e ótima para arborização urbana." },
        { name: "Cássias amarelas", img: speciesImages["Cássias"], desc: "Grande beleza ornamental com cachos amarelos." },
        { name: "Lofantera", img: speciesImages["Lofantera"], desc: "Também conhecida como chuva-de-ouro." },
        { name: "Resedá", img: speciesImages["Resedá"], desc: "Pequeno porte, ideal para calçadas com fiação." },
        { name: "Calicarpa", img: speciesImages["Calicarpa"], desc: "Destaca-se pelos seus pequenos frutos roxos." },
        { name: "Flamboyant de jardim", img: speciesImages["Flamboyant"], desc: "Beleza tropical com cores quentes." },
        { name: "Pitanga", img: speciesImages["Pitanga"], desc: "Frutífera nativa que atrai muitos pássaros." },
        { name: "Araçá", img: speciesImages["Pitanga"], desc: "Frutos saborosos e árvore de pequeno porte." },
        { name: "Cássia canudo de pito", img: speciesImages["Cássia Canudo"], desc: "Floração intensa e muito decorativa." },
        { name: "Tingui preto", img: speciesImages["Tingui"], desc: "Nativa resistente e muito elegante." }
    ]

    const [selectedSpecies, setSelectedSpecies] = useState(speciesData[0])
    const [searchTerm, setSearchTerm] = useState('')


    const filteredSpecies = speciesData.filter(species =>
        species.name.toLowerCase().includes(searchTerm.toLowerCase())
    )

    const [showStudybookDetails, setShowStudybookDetails] = useState(false);

    return (
        <section className={styles.sama_container}>


            <section id="sama-intro" className={styles.intro_row_section}>
                {/* Full Background Leaves - Spread Everywhere including behind text */}
                <div className={styles.full_background_leaves}>
                    {[...Array(25)].map((_, i) => (
                        <FaLeaf
                            key={`bg-leaf-${i}`}
                            className={`${styles.background_leaf_pulsing} ${styles['leaf_pulse_' + (i % 6)]}`}
                            style={{
                                left: `${(i * 4) + Math.random() * 2}%`, // Spread across entire width
                                top: `${Math.random() * 95}%`, // Full height
                                animationDelay: `${Math.random() * 8}s`,
                                fontSize: `${1.8 + Math.random() * 1.5}rem`, // Large and visible
                                opacity: 0 // Will fade in via animation
                            }}
                        />
                    ))}
                </div>

                <div className={styles.intro_row_content}>
                    <div className={styles.intro_text_container}>
                        <h1 className={styles.intro_main_title}>SEJAM BEM-VINDOS</h1>
                        <div className={styles.intro_main_text}>
                            <p>
                                A <strong>SAMA</strong> atua como o coração ecológico de Garça, unindo tecnologia e natureza para promover o desenvolvimento sustentável. Nossa missão é integrar a força do produtor rural à preservação rigorosa dos nossos tesouros naturais.
                            </p>
                            <p>
                                Comprometidos com a restauração de nossos ecossistemas, cuidamos com dedicação das matas e fauna locais, garantindo que as futuras gerações herdem uma Garça vibrante, verde e em pleno equilíbrio ambiental.
                            </p>
                        </div>
                    </div>

                    <div className={styles.intro_image_container}>
                        <img
                            src={capaSama}
                            alt="SAMA Logo"
                            className={styles.intro_square_image}
                        />
                    </div>
                </div>


            </section>

            {/* 2. Atendimento e Serviços Section (secretaria.jpeg background) - Moved Up */}
            <section
                className={styles.benefits_combined_section}
                style={{
                    backgroundImage: `linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url(${secretariaImg})`
                }}
            >
                <div className={styles.benefits_overlay}>
                    <div className={styles.benefit_box_left}>
                        <h2 className={styles.benefit_title}>Atendimento SAMA</h2>
                        <div className={styles.benefit_divider}></div>
                        <p className={styles.benefit_text}>
                            Estamos à disposição para atender a comunidade, tirar dúvidas sobre licenciamento ambiental, manejo de vegetação e denúncias. Nosso atendimento é focado na agilidade e transparência.
                        </p>
                    </div>

                    <div className={styles.benefit_spacer}></div>

                    <div className={styles.benefit_box_right}>
                        <h2 className={styles.benefit_title}>Orientações Técnicas</h2>
                        <div className={styles.benefit_divider}></div>
                        <p className={styles.benefit_text}>
                            Oferecemos suporte técnico para produtores e cidadãos que desejam realizar o plantio adequado de mudas ou necessitam de orientações sobre a legislação ambiental vigente em nosso município.
                        </p>
                    </div>
                </div>
            </section>
            {/* 3. Studybook Text Section (Clean Style - matching Denounce) */}
            <section className={styles.research_row_section}>
                <div className={styles.research_clean_container}>
                    <h2 className={styles.research_card_title}>Projeto Studybook de Bugios</h2>

                    <div className={styles.title_decoration_sama}>
                        <span className={styles.line_sama}></span>
                        <span className={styles.dot_sama}></span>
                        <span className={styles.dot_sama}></span>
                    </div>

                    <div className={styles.research_card_text_large}>
                        <p style={{ color: '#446042', fontWeight: 'bold', fontSize: '1.4rem', marginBottom: '1.5rem', textTransform: 'uppercase', letterSpacing: '1px' }}>
                            Educação Ambiental e Ciência Cidadã
                        </p>
                        <p>
                            O <strong>Projeto Studybook de Bugios</strong> é uma iniciativa interativa de ponta desenvolvida para zoológicos modernos. Os bugios (<em>Alouatta sp.</em>) são primatas vitais para o ecossistema brasileiro, conhecidos como os "guardiões das matas" pelo seu som potente e papel fundamental na dispersão de sementes.
                        </p>
                        <p>
                            Diferente de uma simples placa, o <strong>Studybook</strong> oferece um guia dinâmico que transforma a visita ao zoo em uma aula de campo. O projeto conscientiza sobre a preservação ambiental, aproxima o público da realidade científica dos animais e incentiva o respeito absoluto ao habitat natural.
                        </p>
                        <p style={{ marginTop: '1rem', fontWeight: '500', color: '#446042', fontStyle: 'italic' }}>
                            🌿 Por que é essencial no Zoo? Porque transformamos curiosidade em conservação ativa.
                        </p>
                    </div>

                    <div style={{ marginTop: '2.5rem' }}>
                        <button
                            className={styles.conhecer_button}
                            onClick={() => setShowStudybookDetails(!showStudybookDetails)}
                        >
                            {showStudybookDetails ? "OCULTAR DETALHES" : "CONHECER OBJETIVOS DO PROJETO"}
                        </button>
                    </div>

                    {showStudybookDetails && (
                        <div className={styles.expanded_research_text_clean}>
                            <h4 style={{ color: '#446042', marginBottom: '1.5rem', fontFamily: 'Rubik, sans-serif', fontSize: '1.4rem', fontWeight: '700' }}>
                                Nossas Metas de Conservação:
                            </h4>
                            <ul className={styles.clean_meta_list}>
                                <li><strong>Educação Lúdica:</strong> Ensinar biologia sem ser cansativo.</li>
                                <li><strong>Consciência Ambiental:</strong> Transformar visitantes em protetores da fauna.</li>
                                <li><strong>Pesquisa Técnica:</strong> Apoiar o mapeamento populacional das espécies.</li>
                                <li><strong>Respeito Animal:</strong> Ensinar o público a observar sem interferir no habitat.</li>
                                <li><strong>Interatividade:</strong> Tornar a experiência do zoológico moderna e inesquecível.</li>
                            </ul>
                        </div>
                    )}
                </div>
            </section>

            {/* New Bugios Cards Section */}
            {/* New Bugios Cards Section */}
            <section
                className={styles.benefits_combined_section}
                style={{
                    backgroundImage: `linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url(${bugiosImg})`
                }}
            >
                <div className={styles.benefits_overlay}>
                    <div className={styles.benefit_box_left}>
                        <h2 className={styles.benefit_title}>Quem são os Bugios?</h2>
                        <div className={styles.benefit_divider}></div>
                        <p className={styles.benefit_text}>
                            Os bugios são primatas que vivem em florestas brasileiras e são conhecidos pelo seu som forte, usado para se comunicar e marcar território. Vivem em grupos, se alimentam principalmente de folhas e frutos e passam grande parte do tempo nas árvores.
                        </p>
                    </div>

                    <div className={styles.benefit_spacer}></div>

                    <div className={styles.benefit_box_right}>
                        <h2 className={styles.benefit_title}>Importância na Natureza</h2>
                        <div className={styles.benefit_divider}></div>
                        <p className={styles.benefit_text}>
                            Os bugios são essenciais para o equilíbrio da floresta, pois ajudam na dispersão de sementes e na regeneração natural da vegetação. Além disso, a presença deles indica que o ambiente está saudável, sendo importantes para a biodiversidade e para a preservação do ecossistema.
                        </p>
                    </div>
                </div>
            </section >


            {/* 4. Carousel Section (Zoologico Model) */}
            < div className={styles.carousel_section_container} >
                <div className={styles.carousel_title_wrapper}>
                    <h2 className={styles.galleryTitle}>Galeria SAMA</h2>
                </div>
                <div className={styles.species_carousel_wrapper}>
                    <button className={`${styles.navButton} ${styles.prevButton}`} onClick={prevAnimalSlide}>
                        <FaChevronLeft />
                    </button>

                    <div
                        ref={carouselTrackRef}
                        className={`${styles.species_carousel_track} ${isDragging ? styles.dragging : ''}`}
                        style={{ transform: `translateX(calc(-${currentAnimalSlide * (100 / animalsPerView)}% + ${dragOffset}px))` }}
                        onMouseDown={handleMouseDown}
                        onMouseLeave={handleMouseLeave}
                        onMouseUp={handleMouseUp}
                        onMouseMove={handleMouseMove}
                        onTouchStart={handleTouchStart}
                        onTouchMove={handleTouchMove}
                        onTouchEnd={handleMouseUp}
                    >
                        {researchAnimals.map((img, idx) => (
                            <div key={idx} className={styles.carousel_item_square} style={{ flex: `0 0 ${100 / animalsPerView}%` }}>
                                <div
                                    className={styles.carousel_square_image}
                                    style={{
                                        backgroundImage: `url(${img})`,
                                        backgroundPosition: 'center'
                                    }}
                                >
                                </div>
                            </div>
                        ))}
                    </div>

                    <button className={`${styles.navButton} ${styles.nextButton}`} onClick={nextAnimalSlide}>
                        <FaChevronRight />
                    </button>
                </div>
                <div className={styles.carousel_dots}>
                    {researchAnimals.slice(0, researchAnimals.length - (animalsPerView - 1)).map((_, idx) => (
                        <span
                            key={idx}
                            className={`${styles.dot} ${idx === currentAnimalSlide ? styles.active_dot : ''}`}
                            onClick={() => setCurrentAnimalSlide(idx)}
                        ></span>
                    ))}
                </div>
            </div >

            {/* 6. Bugio/Fauna Clean Text Section (Moved here) */}
            < section className={styles.research_row_section} >
                {/* Full Background Leaves - Nature Section */}
                < div className={styles.full_background_leaves} >
                    {
                        [...Array(25)].map((_, i) => (
                            <FaLeaf
                                key={`bg-leaf-nature-${i}`}
                                className={`${styles.nature_leaf_fade} ${styles['leaf_fade_' + (i % 6)]}`}
                                style={{
                                    left: `${(i * 4) + Math.random() * 2}%`,
                                    top: `${Math.random() * 95}%`,
                                    animationDelay: `${Math.random() * 8}s`,
                                    fontSize: `${1.8 + Math.random() * 1.5}rem`,
                                    opacity: 0
                                }}
                            />
                        ))
                    }
                </div >

                <div className={styles.research_clean_container}>
                    <h2 className={styles.research_card_title}>Natureza e Preservação</h2>

                    <div className={styles.title_decoration_sama}>
                        <span className={styles.line_sama}></span>
                        <span className={styles.dot_sama}></span>
                        <span className={styles.dot_sama}></span>
                    </div>

                    <div className={styles.research_card_text_large}>
                        <p>
                            A preservação do meio ambiente é essencial para garantir a qualidade de vida e o futuro do nosso planeta. A fauna silvestre desempenha uma função crucial nesse processo, atuando como reguladora natural dos ecossistemas. Os bugios, por exemplo, são fundamentais para a renovação das florestas, espalhando sementes que garantem o nascimento de novas árvores e a manutenção das áreas verdes.
                        </p>

                        <p style={{ color: '#446042', fontWeight: 'bold', fontSize: '1.4rem', marginTop: '1.5rem', marginBottom: '1rem', textTransform: 'uppercase', letterSpacing: '1px' }}>
                            Biodiversidade
                        </p>

                        <p>
                            Conservar a natureza é um dever de todos. Ao protegermos os habitats naturais, asseguramos a sobrevivência de inúmeras espécies e a continuidade dos serviços ambientais que a natureza nos oferece, como ar puro e água limpa. Nosso compromisso é promover uma consciência ecológica ativa, onde o respeito à vida silvestre seja a base para um desenvolvimento verdadeiramente sustentável em Garça.
                        </p>
                    </div>
                </div>
            </section >


            {/* 3. Interactive Species Section (Tree Carousel) */}
            < div className={styles.species_section} >
                <div className={styles.species_container}>
                    <h2 className={styles.sub_title}>Indicação de Espécies</h2>
                    <p className={styles.section_intro}>
                        Selecione uma espécie para ver detalhes e fotos. As de <strong>pequeno porte</strong> são indicadas para calçadas com fiação elétrica.
                    </p>

                    <div className={styles.search_container}>
                        <div className={styles.search_input_wrapper}>
                            <FaSearch className={styles.search_icon} />
                            <input
                                type="text"
                                placeholder="Digite o nome da espécie..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className={styles.search_input}
                            />
                        </div>
                    </div>

                    <div className={styles.interactive_flex}>
                        <div className={styles.species_list}>
                            {filteredSpecies.length > 0 ? (
                                filteredSpecies.map((item, index) => (
                                    <button
                                        key={index}
                                        className={`${styles.species_btn} ${selectedSpecies && selectedSpecies.name === item.name ? styles.active_btn : ''}`}
                                        onClick={() => setSelectedSpecies(item)}
                                    >
                                        <FaTree className={styles.tree_icon} />
                                        <span>{item.name}</span>
                                    </button>
                                ))
                            ) : (
                                <p className={styles.no_results}>Nenhuma espécie encontrada.</p>
                            )}
                        </div>

                        <div className={styles.photo_viewer}>
                            {selectedSpecies && (
                                <div className={styles.viewer_card}>
                                    <img
                                        src={selectedSpecies.img}
                                        alt={selectedSpecies.name}
                                        className={styles.viewer_img}
                                    />
                                    <div className={styles.viewer_info}>
                                        <h3>{selectedSpecies.name}</h3>
                                        <p>{selectedSpecies.desc}</p>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div >

            {/* 5. Info Bars Section (Zoologico Model) */}
            < section className={styles.info_section_wrapper} >
                <h2 className={styles.sub_title}>Informações e Contato</h2>
                <div className={styles.infoBarsContainer}>

                    <div className={`${styles.infoBar} ${styles.infoBarGreen}`}>
                        <div className={styles.infoBarIcon}><FaTree /></div>
                        <div className={styles.infoBarContent}>
                            <h3>Selo SAMA</h3>
                            <p>Compromisso com o reflorestamento e proteção da biodiversidade de Garça.</p>
                        </div>
                    </div>

                    <div className={`${styles.infoBar} ${styles.infoBarOrange}`}>
                        <div className={styles.infoBarIcon}><FaSearch /></div>
                        <div className={styles.infoBarContent}>
                            <h3>Pesquisas Ativas</h3>
                            <p>Monitoramento constante da fauna local e corredores ecológicos.</p>
                        </div>
                    </div>

                    <div className={`${styles.infoBar} ${styles.infoBarGreen}`}>
                        <div className={styles.infoBarIcon}><FaPhoneAlt /></div>
                        <div className={styles.infoBarContent}>
                            <h3>Atendimento Munícipe</h3>
                            <p>Dúvidas e solicitações: (14) 3407-6600 | sama@garca.sp.gov.br</p>
                        </div>
                    </div>
                </div>
            </section >

        </section >
    )
}

export default Sama

