import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'
import { useState, useEffect, useRef, useMemo } from 'react'
import styles from './TreesHome.module.css'
import capaArvore from '../../../assets/img/arvore.png'
import capaSamaMobile from '../../../assets/img/capacell/capacelsama.png'

import { FaChevronDown, FaLeaf, FaTree, FaSeedling, FaSearch, FaChevronLeft, FaChevronRight } from 'react-icons/fa'

import benefit1 from './air_quality_v3.png'
import benefit2 from './tree_benefit_2_v2_1769173516137.png'
import benefit3 from './tree_benefit_3_v2_1769173536687.png'

import { speciesImages } from '../../../utils/treeImageMapper'

import ArvoreModal from '../../layout/ArvoreModal'

function TreesHome() {

    const [arvores, setArvores] = useState([])
    const [selectedArvore, setSelectedArvore] = useState(null)
    const [showInfo, setShowInfo] = useState(false)
    const [openFaqIndex, setOpenFaqIndex] = useState(null)
    const [visibleTreesCount, setVisibleTreesCount] = useState(12) // Limit to 12 initially (3 rows)
    const [searchTerm, setSearchTerm] = useState('') // Search filter state
    const [wiringFilter, setWiringFilter] = useState('') // 'true', 'false', or ''
    const missionSectionRef = useRef(null)

    useEffect(() => {
        api.get('/arvores').then((response) => {
            setArvores(response.data.arvores || [])
        })
    }, [])

    const [currentSlide, setCurrentSlide] = useState(0)
    const [isDragging, setIsDragging] = useState(false)
    const [startX, setStartX] = useState(0)
    const [dragOffset, setDragOffset] = useState(0)
    const carouselTrackRef = useRef(null)

    const speciesData = useMemo(() => {
        try {
            return Object.keys(speciesImages).filter(key => key !== "Cássia").map(name => ({
                name,
                img: speciesImages[name]
            }))
        } catch (e) {
            return []
        }
    }, [])

    // Responsive items count
    const getItemsVisible = () => {
        if (window.innerWidth <= 768) return 1 // Match Zoologico (1 item)
        if (window.innerWidth <= 1024) return 2
        return 4
    }

    // Auto-advance logic
    useEffect(() => {
        if (isDragging) return
        const interval = setInterval(() => {
            const itemsVisible = getItemsVisible()
            const maxSlide = Math.max(0, speciesData.length - itemsVisible)
            if (maxSlide > 0) {
                setCurrentSlide((prev) => (prev + 1) % (maxSlide + 1))
            }
        }, 2500)
        return () => clearInterval(interval)
    }, [speciesData.length, isDragging])

    const nextSlide = () => {
        const itemsVisible = getItemsVisible()
        const maxSlide = Math.max(0, speciesData.length - itemsVisible)
        setCurrentSlide(prev => Math.min(prev + 1, maxSlide))
    }

    const prevSlide = () => {
        setCurrentSlide(prev => Math.max(prev - 1, 0))
    }

    // Drag handlers
    const handleMouseDown = (e) => {
        setIsDragging(true)
        setStartX(e.pageX)
        setDragOffset(0)
    }

    const handleMouseMove = (e) => {
        if (!isDragging) return
        e.preventDefault()
        const x = e.pageX
        const walk = (x - startX)
        setDragOffset(walk)
    }

    const handleMouseUp = () => {
        if (!isDragging) return
        setIsDragging(false)

        const trackWidth = carouselTrackRef.current.offsetWidth
        const itemWidth = trackWidth / 4 // 4 items visible
        const movedSlides = Math.round(dragOffset / itemWidth)

        const maxSlide = Math.max(0, speciesData.length - 4)
        let newSlide = currentSlide - movedSlides

        // Clamp newSlide
        newSlide = Math.max(0, Math.min(newSlide, maxSlide))

        setCurrentSlide(newSlide)
        setDragOffset(0)
    }

    const handleMouseLeave = () => {
        if (isDragging) handleMouseUp()
    }

    // Touch handlers (simplified to use same logic)
    const handleTouchStart = (e) => {
        setIsDragging(true)
        setStartX(e.touches[0].pageX)
        setDragOffset(0)
    }

    const handleTouchMove = (e) => {
        if (!isDragging) return
        const x = e.touches[0].pageX
        const walk = (x - startX)
        setDragOffset(walk)
    }


    const scrollToMission = () => {
        if (missionSectionRef.current) {
            missionSectionRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' })
        }
    }

    return (
        <section className={styles.page_section}>
            <div className={styles.nature_background}>
                <FaLeaf className={`${styles.decor_icon} ${styles.pos_1}`} />
                <FaTree className={`${styles.decor_icon} ${styles.pos_2}`} />
                <FaSeedling className={`${styles.decor_icon} ${styles.pos_3}`} />
                <FaLeaf className={`${styles.decor_icon} ${styles.pos_4}`} />
                {/* Removed pos_5 tree near importance */}
                <FaSeedling className={`${styles.decor_icon} ${styles.pos_6}`} />
                <FaLeaf className={`${styles.decor_icon} ${styles.pos_7}`} />
                <FaTree className={`${styles.decor_icon} ${styles.pos_8}`} />
                <FaSeedling className={`${styles.decor_icon} ${styles.pos_9}`} />
                <FaLeaf className={`${styles.decor_icon} ${styles.pos_10}`} />
                {/* Removed pos_11 tree near importance */}
                <FaSeedling className={`${styles.decor_icon} ${styles.pos_12}`} />
            </div>

            {/* Banner Principal (Restaurado Inteiro) */}
            <div className={styles.hero_section}>
                <div className={styles.hero_image_wrapper}>
                    <img
                        src={capaArvore}
                        alt="Sama Garça"
                        className={styles.hero_image_desktop}
                    />
                </div>
                <img
                    src={capaSamaMobile}
                    alt="Sama Garça Mobile"
                    className={styles.hero_image_mobile}
                />
                <div className={styles.hero_content}>
                    <h1 className={`${styles.hero_title} ${styles.animate_fade_up}`}>Semeando o <br />Futuro</h1>
                    <p className={`${styles.hero_subtitle} ${styles.animate_fade_up} ${styles.delay_1}`}>
                        Transforme Garça em uma cidade mais verde. <br />
                        Solicite sua muda e renove o ambiente hoje mesmo.
                    </p>
                    <button onClick={scrollToMission} className={`${styles.hero_button} ${styles.animate_fade_up} ${styles.delay_2}`}>Conheça nosso plantio</button>
                </div>
            </div>

            <div ref={missionSectionRef} className={styles.tree_home_header}>
                <h1 className={styles.klinic_font}>Veja nosso Plantio</h1>
                <p>Confira abaixo as mudas disponíveis para plantio em nossa cidade. Contribua para uma Garça mais verde e sustentável solicitando sua muda hoje mesmo.</p>

                <button
                    onClick={() => setShowInfo(!showInfo)}
                    className={styles.info_button}
                >
                    {showInfo ? 'Ocultar Guia' : 'Como solicitar minha muda?'}
                </button>

                {showInfo && (
                    <div className={styles.info_text}>
                        <p>
                            <strong>Guia de Solicitação:</strong> <br /><br />
                            <strong>Passo 1:</strong> Escolha a espécie que melhor se adapta ao seu espaço. <br />
                            <strong>Passo 2:</strong> Clique em "Solicitar" para ver os detalhes e informar o endereço. <br />
                            <strong>Passo 3:</strong> A SAMA analisará seu pedido e entrará em contato para agendar o plantio.
                        </p>
                    </div>
                )}
            </div>

            <div className={styles.filter_section}>
                <h3 className={styles.filter_title}>Buscar Espécie:</h3>

                <div className={styles.filter_row}>
                    <select
                        className={styles.filter_select}
                        value={wiringFilter}
                        onChange={(e) => setWiringFilter(e.target.value)}
                    >
                        <option value="">Fiação: Todas</option>
                        <option value="true">Aceita Fiação</option>
                        <option value="false">Não Aceita Fiação</option>
                    </select>

                    <div className={styles.search_container}>
                        <FaSearch className={styles.search_icon} />
                        <input
                            type="text"
                            placeholder="Digite o nome da espécie..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className={styles.search_input}
                        />
                        {searchTerm && (
                            <button
                                className={styles.clear_button}
                                onClick={() => setSearchTerm('')}
                                aria-label="Limpar busca"
                            >
                                ✕
                            </button>
                        )}
                    </div>
                </div>
                {searchTerm && (
                    <p className={styles.search_results_text}>
                        {arvores.filter(arvore =>
                            arvore.species.toLowerCase().includes(searchTerm.toLowerCase())
                        ).length} resultado(s) encontrado(s)
                    </p>
                )}
            </div>

            <div className={styles.tree_container}>
                {arvores.length > 0 &&
                    arvores
                        .filter(arvore =>
                            (searchTerm === '' ||
                                arvore.species.toLowerCase().includes(searchTerm.toLowerCase()) ||
                                arvore.location.toLowerCase().includes(searchTerm.toLowerCase())) &&
                            (wiringFilter === '' || String(arvore.allowsWiring) === wiringFilter)
                        )
                        .slice(0, visibleTreesCount)
                        .map((arvore, index) => (
                            <div key={arvore._id} className={`${styles.tree_card} ${styles.fade_in}`} style={{ animationDelay: `${index * 0.1}s` }}>
                                <div className={styles.tree_card_image_container}>
                                    {arvore.images && arvore.images.length > 0 && (
                                        <div
                                            className={styles.tree_card_image}
                                            style={{
                                                backgroundImage: `url(${getApiBase()}/images/arvores/${arvore.images[0]})`
                                            }}
                                        ></div>
                                    )}
                                    {arvore.available && (
                                        <div className={styles.badge_available}>Disponível</div>
                                    )}
                                </div>
                                <div className={styles.tree_card_content}>
                                    <h3 className={styles.species_title}>{arvore.species}</h3>
                                    <p className={styles.tree_info_row}>
                                        <span className={styles.bold_label}>Local:</span> {arvore.location}
                                    </p>
                                    <p className={styles.tree_info_row}>
                                        <span className={styles.bold_label}>Qtd:</span> {arvore.quantity}
                                    </p>
                                    <p className={styles.tree_info_row} style={{ fontSize: '0.9rem' }}>
                                        <span className={styles.bold_label}>Fiação:</span>
                                        {arvore.allowsWiring ?
                                            <span style={{ color: '#749666', fontWeight: 'bold' }}>Permitida ✅</span> :
                                            <span style={{ color: '#e74c3c', fontWeight: 'bold' }}>Não indicada ⚠️</span>
                                        }
                                    </p>
                                    {arvore.available && arvore.quantity > 0 && arvore._id ? (
                                        <button
                                            onClick={() => setSelectedArvore(arvore)}
                                            className={styles.details_button}
                                        >
                                            Solicitar
                                        </button>
                                    ) : (
                                        <p className={styles.adopted_text}>Indisponível</p>
                                    )}
                                </div>
                            </div>
                        ))}
            </div>

            {/* Load More Button */}
            {visibleTreesCount < arvores.length && (
                <div className={styles.load_more_container}>
                    <button
                        className={styles.load_more_button}
                        onClick={() => setVisibleTreesCount(prev => prev + 12)}
                    >
                        Ver todas as mudas
                    </button>
                </div>
            )}

            {/* Importance Section (Background Images + Dark Overlay) */}
            <div className={styles.importance_section}>
                <div className={styles.importance_header}>
                    <h2 className={styles.importance_title}>Por que escolher uma planta?</h2>
                </div>

                <div className={styles.importance_container}>
                    <div className={styles.importance_card} style={{ backgroundImage: `url(${benefit1})` }}>
                        <div className={styles.importance_overlay}>
                            <div className={styles.importance_text}>
                                <p><strong>Ar mais puro:</strong> Árvores agem como purificadores naturais, filtrando poluentes e garantindo oxigênio vital para sua família.</p>
                            </div>
                        </div>
                    </div>

                    <div className={styles.importance_card} style={{ backgroundImage: `url(${benefit2})` }}>
                        <div className={styles.importance_overlay}>
                            <div className={styles.importance_text}>
                                <p><strong>Clima e Sombra:</strong> O plantio estratégico reduz a temperatura urbana, criando microclimas frescos e sombras para o lazer.</p>
                            </div>
                        </div>
                    </div>

                    <div className={styles.importance_card} style={{ backgroundImage: `url(${benefit3})` }}>
                        <div className={styles.importance_overlay}>
                            <div className={styles.importance_text}>
                                <p><strong>Mais Natureza:</strong> Atraia pássaros e beleza para seu bairro. Cada árvore é um ecossistema vivo que protege nossa fauna local.</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Species Carousel Section (Bottom quadratinhos) */}
            <div className={styles.carousel_section_container}>
                <div className={styles.carousel_title_wrapper}>
                    <h2 className={styles.klinic_font}>Conheça nossas Espécies</h2>
                </div>
                <div className={styles.species_carousel_outer}>
                    <button className={`${styles.carousel_arrow} ${styles.arrow_left}`} onClick={prevSlide} aria-label="Anterior">
                        <FaChevronLeft />
                    </button>

                    <div className={styles.species_carousel_wrapper}>
                        <div
                            ref={carouselTrackRef}
                            className={`${styles.species_carousel_track} ${isDragging ? styles.dragging : ''}`}
                            style={{
                                transform: `translateX(calc(-${currentSlide * (100 / getItemsVisible())}% + ${dragOffset}px))`
                            }}
                            onMouseDown={handleMouseDown}
                            onMouseLeave={handleMouseLeave}
                            onMouseUp={handleMouseUp}
                            onMouseMove={handleMouseMove}
                            onTouchStart={handleTouchStart}
                            onTouchMove={handleTouchMove}
                            onTouchEnd={handleMouseUp}
                        >
                            {speciesData.map((species, index) => (
                                <div key={index} className={styles.carousel_item_square}>
                                    <div
                                        className={styles.carousel_square_image}
                                        style={{ backgroundImage: `url(${species.img})` }}
                                    >
                                        <div className={styles.square_label}>{species.name}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <button className={`${styles.carousel_arrow} ${styles.arrow_right}`} onClick={nextSlide} aria-label="Próximo">
                        <FaChevronRight />
                    </button>
                </div>
                <div className={styles.carousel_dots}>
                    {speciesData.slice(0, speciesData.length - 3).map((_, index) => (
                        <span
                            key={index}
                            className={`${styles.dot} ${index === currentSlide ? styles.active_dot : ''}`}
                            onClick={() => setCurrentSlide(index)}
                        ></span>
                    ))}
                </div>
            </div>

            {/* FAQ Section (Personalized) */}
            <div className={styles.custom_faq_section}>
                {/* Floating Leaves Animation - Visual Effect */}
                <FaLeaf className={styles.faq_leaf} style={{ left: '5%', animationDuration: '15s', animationDelay: '0s', fontSize: '1.8rem' }} />
                <FaLeaf className={styles.faq_leaf} style={{ left: '25%', animationDuration: '12s', animationDelay: '2s', fontSize: '1.2rem' }} />
                <FaLeaf className={styles.faq_leaf} style={{ left: '50%', animationDuration: '18s', animationDelay: '5s', fontSize: '1.5rem' }} />
                <FaLeaf className={styles.faq_leaf} style={{ right: '20%', animationDuration: '14s', animationDelay: '1s', fontSize: '1.6rem' }} />
                <FaLeaf className={styles.faq_leaf} style={{ right: '5%', animationDuration: '10s', animationDelay: '3s', fontSize: '1.3rem' }} />

                <div className={styles.custom_faq_header}>
                    <h2 className={styles.custom_faq_title}>
                        Dúvidas sobre Mudas
                    </h2>
                </div>

                <div className={styles.custom_faq_container}>
                    <div
                        className={`${styles.custom_faq_item} ${openFaqIndex === 0 ? styles.custom_faq_item_open : ''}`}
                        onClick={() => setOpenFaqIndex(openFaqIndex === 0 ? null : 0)}
                    >
                        <div className={styles.custom_faq_question}>
                            <h3>Quem pode solicitar uma muda?</h3>
                            <FaChevronDown className={styles.custom_faq_chevron} />
                        </div>
                        <div className={styles.custom_faq_answer}>
                            <p>Qualquer morador de Garça que possua um espaço adequado para o plantio e compromisso com o cuidado da muda.</p>
                        </div>
                    </div>

                    <div
                        className={`${styles.custom_faq_item} ${openFaqIndex === 1 ? styles.custom_faq_item_open : ''}`}
                        onClick={() => setOpenFaqIndex(openFaqIndex === 1 ? null : 1)}
                    >
                        <div className={styles.custom_faq_question}>
                            <h3>As mudas são gratuitas?</h3>
                            <FaChevronDown className={styles.custom_faq_chevron} />
                        </div>
                        <div className={styles.custom_faq_answer}>
                            <p>Sim, o projeto visa incentivar a arborização urbana sem custos de aquisição para o cidadão.</p>
                        </div>
                    </div>

                    <div
                        className={`${styles.custom_faq_item} ${openFaqIndex === 2 ? styles.custom_faq_item_open : ''}`}
                        onClick={() => setOpenFaqIndex(openFaqIndex === 2 ? null : 2)}
                    >
                        <div className={styles.custom_faq_question}>
                            <h3>A SAMA faz o plantio?</h3>
                            <FaChevronDown className={styles.custom_faq_chevron} />
                        </div>
                        <div className={styles.custom_faq_answer}>
                            <p>O plantio pode ser realizado pela SAMA ou pelo cidadão, dependendo do local e da espécie solicitada. Detalhes são acertados após a solicitação.</p>
                        </div>
                    </div>

                    <div
                        className={`${styles.custom_faq_item} ${openFaqIndex === 3 ? styles.custom_faq_item_open : ''}`}
                        onClick={() => setOpenFaqIndex(openFaqIndex === 3 ? null : 3)}
                    >
                        <div className={styles.custom_faq_question}>
                            <h3>Posso escolher qualquer espécie?</h3>
                            <FaChevronDown className={styles.custom_faq_chevron} />
                        </div>
                        <div className={styles.custom_faq_answer}>
                            <p>Temos uma variedade de espécies nativas e ornamentais disponíveis. A escolha depende da disponibilidade do viveiro e da adequação ao local de plantio (calçada, quintal, etc).</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal */}
            {selectedArvore && (
                <ArvoreModal arvore={selectedArvore} onClose={() => setSelectedArvore(null)} />
            )}
        </section>
    )
}

export default TreesHome
