import { getApiBase } from '../../utils/api'

import { useRef } from 'react'
import { FaChevronLeft, FaChevronRight } from 'react-icons/fa'
import styles from './PetCarousel.module.css'

function PetCarousel({ pets, isAdopted = false, onAdoptClick }) {
    const carouselRef = useRef(null)

    const scrollLeft = () => {
        if (carouselRef.current) {
            carouselRef.current.scrollBy({ left: -300, behavior: 'smooth' })
        }
    }

    const scrollRight = () => {
        if (carouselRef.current) {
            carouselRef.current.scrollBy({ left: 300, behavior: 'smooth' })
        }
    }

    if (!pets || pets.length === 0) return null

    return (
        <div className={styles.carousel_wrapper}>
            <button className={`${styles.nav_button} ${styles.left}`} onClick={scrollLeft}>
                <FaChevronLeft />
            </button>

            <div className={styles.carousel_container} ref={carouselRef}>
                {pets.map((pet) => (
                    <div key={pet._id} className={styles.pet_card}>
                        {pet.images && pet.images.length > 0 && pet.images[0] ? (
                            <div
                                style={{
                                    backgroundImage: `url(${getApiBase()}/images/pets/${pet.images[0]})`
                                }}
                                className={styles.pet_card_image}>
                            </div>
                        ) : (
                            <div
                                style={{
                                    backgroundColor: '#e0e0e0',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    color: '#999',
                                    height: '200px'
                                }}
                                className={styles.pet_card_image}>
                                <span>Sem imagem</span>
                            </div>
                        )}
                        <div className={styles.pet_card_content}>
                            <h3>{pet.name}</h3>
                            {isAdopted ? (
                                <p className={styles.adopted_label}>Adotado</p>
                            ) : (
                                <>
                                    {pet.breed && <p className={styles.pet_detail}><strong>Raça:</strong> {pet.breed}</p>}
                                    {pet.gender && <p className={styles.pet_detail}><strong>Gênero:</strong> {pet.gender}</p>}
                                    <button
                                        className={styles.adopt_button}
                                        onClick={() => onAdoptClick && onAdoptClick(pet)}
                                    >
                                        Me Adote!
                                    </button>
                                </>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            <button className={`${styles.nav_button} ${styles.right}`} onClick={scrollRight}>
                <FaChevronRight />
            </button>
        </div>
    )
}

export default PetCarousel
