import styles from './AddPet.module.css'

/* components */
import PetForm from '../../form/PetForm'
import { useState, useEffect } from 'react'
import useFlashMessage from '../../../hooks/useFlashMessage'
import { useHistory } from 'react-router-dom/cjs/react-router-dom.min'
import api from '../../../utils/api'

function AddPet() {
    const [token] = useState(localStorage.getItem('token') || '')
    const { setFlashMessage } = useFlashMessage()
    const history = useHistory()

    useEffect(() => {
        if (token) {
            api.get('/pets/mypets', {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
                .then((response) => {
                    const pets = response.data.pets || []
                    // Se não tem pets cadastrados, verificar se tem adoções
                    if (pets.length === 0) {
                        api.get('/pets/myadoptions', {
                            headers: {
                                Authorization: `Bearer ${JSON.parse(token)}`
                            }
                        })
                            .then((response) => {
                                const adoptions = response.data.pets || []
                                // Se tem adoções mas não tem pets, é adotante e não pode cadastrar
                                if (adoptions.length > 0) {
                                    setFlashMessage('Você é um adotante e não pode cadastrar pets para adoção.', 'error')
                                    history.push('/pet/myadoptions')
                                }
                            })
                            .catch(() => { })
                    }
                })
                .catch(() => { })
        }
    }, [token, history]) // eslint-disable-line react-hooks/exhaustive-deps


    async function register(pet) {

        let msgType = 'success'

        const formData = new FormData()

        Object.keys(pet).forEach((key) => {

            if (key === 'images' && pet[key] && pet[key].length > 0) {

                for (let i = 0; i < pet[key].length; i++) {
                    formData.append('images', pet[key][i])
                }

            } else if (key !== 'images' && pet[key] !== null && pet[key] !== undefined && pet[key] !== '') {
                formData.append(key, pet[key])
            }
        })

        const data = await api.post('pets/create', formData, {
            headers: {
                Authorization: `Bearer ${JSON.parse(token)}`
            }
        })
            .then((response) => {
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao cadastrar pet' }
            })

        setFlashMessage(data.message, msgType)
        if (msgType !== 'error')
            history.push('/pet/mypets')

    }
    return (
        <section className={styles.addpet_header}>
            <div>
                <h1>Cadastre um Pet</h1>
                <p>Depois ele ficará disponivel para adoção</p>
            </div>
            <p>Formulário</p>
            <PetForm handleSubmit={register} btnText="Cadastrar Pet" />
        </section>
    )
}

export default AddPet
