import api from '../../utils/api'
import { getApiBase } from '../../utils/api'
import { useState } from 'react'
import { FaTimes, FaChevronLeft, FaChevronRight, FaExclamationTriangle } from 'react-icons/fa'
import { Link } from 'react-router-dom'
import useFlashMessage from '../../hooks/useFlashMessage'
import styles from './PetModal.module.css'

function PetModal({ pet, onClose }) {
    const [currentImageIndex, setCurrentImageIndex] = useState(0)
    const [token] = useState(localStorage.getItem('token') || '')
    const [showAddressForm, setShowAddressForm] = useState(false)
    const [address, setAddress] = useState('')
    const { setFlashMessage } = useFlashMessage()

    if (!pet) return null

    const images = pet.images || []

    const nextImage = () => {
        if (images.length > 0) {
            setCurrentImageIndex((prev) => (prev + 1) % images.length)
        }
    }

    const prevImage = () => {
        if (images.length > 0) {
            setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length)
        }
    }

    async function scheduleVisit() {
        if (!address.trim()) {
            setFlashMessage('Por favor, informe o endereço de entrega', 'error')
            return
        }

        let msgType = 'success'

        const data = await api
            .patch(`/pets/schedule/${pet._id}`, {
                deliveryAddress: address.trim()
            }, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
            .then((response) => {
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao solicitar adoção.' }
            })

        if (msgType === 'success') {
            setFlashMessage(data.message || 'Solicitação enviada com sucesso!', msgType)
            setShowAddressForm(false)
            setAddress('')
            setTimeout(() => {
                onClose()
                window.location.reload()
            }, 2000)
        } else {
            setFlashMessage(data.message, msgType)
        }
    }

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <button className={styles.close_button} onClick={onClose}>
                    <FaTimes />
                </button>

                <div className={styles.content}>
                    <div className={styles.carousel_section}>
                        {images.length > 0 ? (
                            <div className={styles.image_container}>
                                <div
                                    className={styles.main_image}
                                    style={{
                                        backgroundImage: `url(${getApiBase()}/images/pets/${images[currentImageIndex]})`
                                    }}
                                />
                                {images.length > 1 && (
                                    <>
                                        <button className={styles.nav_btn} onClick={prevImage}><FaChevronLeft /></button>
                                        <button className={`${styles.nav_btn} ${styles.nav_right}`} onClick={nextImage}><FaChevronRight /></button>
                                        <div className={styles.dots}>
                                            {images.map((_, idx) => (
                                                <span
                                                    key={idx}
                                                    className={`${styles.dot} ${idx === currentImageIndex ? styles.active_dot : ''}`}
                                                    onClick={() => setCurrentImageIndex(idx)}
                                                />
                                            ))}
                                        </div>
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className={styles.no_image}>
                                <p>Sem imagem</p>
                            </div>
                        )}
                    </div>

                    <div className={styles.info_section}>
                        <h2 className={styles.pet_name}>{pet.name}</h2>

                        <div className={styles.details_grid}>
                            {pet.age && <p><strong>Idade:</strong> {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} anos`}</p>}
                            {pet.weight && <p><strong>Peso:</strong> {pet.weight}kg</p>}
                            {pet.color && <p><strong>Cor:</strong> {pet.color}</p>}
                            {pet.gender && <p><strong>Gênero:</strong> {pet.gender}</p>}
                            {pet.breed && <p><strong>Raça:</strong> {pet.breed}</p>}
                            {pet.user && (
                                <>
                                    <p><strong>Doador:</strong> {pet.user.userType === 'Instituto' && pet.user.instituteName ? pet.user.instituteName : pet.user.name}</p>
                                    {pet.user.phone && <p><strong>Telefone:</strong> {pet.user.phone}</p>}
                                </>
                            )}
                        </div>

                        {pet.description && (
                            <div className={styles.description}>
                                <h3>Sobre:</h3>
                                <p>{pet.description}</p>
                            </div>
                        )}

                        <div className={styles.actions}>
                            {token ? (
                                pet.available ? (
                                    !showAddressForm ? (
                                        <button onClick={() => setShowAddressForm(true)} className={styles.adopt_btn}>
                                            Solicitar Adoção
                                        </button>
                                    ) : (
                                        <div className={styles.address_form_container}>
                                            <div className={styles.form_header}>
                                                <label className={styles.form_label}>
                                                    Qual o seu endereço?
                                                </label>
                                                <p className={styles.form_subtitle}>O doador precisa conhecer o local onde o pet irá viver:</p>
                                            </div>
                                            <textarea
                                                value={address}
                                                onChange={(e) => setAddress(e.target.value)}
                                                placeholder="Ex: Rua, Número, Bairro, Cidade..."
                                                className={styles.address_textarea}
                                            />
                                            <div className={styles.form_buttons}>
                                                <button
                                                    onClick={scheduleVisit}
                                                    className={styles.submit_button}
                                                >
                                                    Enviar
                                                </button>
                                                <button
                                                    onClick={() => {
                                                        setShowAddressForm(false)
                                                        setAddress('')
                                                    }}
                                                    className={styles.cancel_button}
                                                >
                                                    Cancelar
                                                </button>
                                            </div>
                                        </div>
                                    )
                                ) : (
                                    <div className={styles.status_message}>
                                        <FaExclamationTriangle className={styles.status_icon} />
                                        <span>Pet já adotado/indisponível.</span>
                                    </div>
                                )
                            ) : (
                                <div className={styles.login_prompt}>
                                    <p>
                                        Você precisa <Link to="/login" className={styles.link_bold}>entrar</Link> ou <Link to="/register" className={styles.link_bold}>criar conta</Link> para adotar.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default PetModal
