import api from '../../../utils/api'

import { useState, useEffect } from 'react'
import { useParams, useHistory } from 'react-router-dom'

import styles from './AddArvore.module.css'

import ArvoreForm from '../../form/ArvoreForm'

/* hooks */
import useFlashMessage from '../../../hooks/useFlashMessage'

function EditArvore() {

  const [arvore, setArvore] = useState({})
  const [token] = useState(localStorage.getItem('token') || '')
  const { id } = useParams()
  const { setFlashMessage } = useFlashMessage()
  const history = useHistory()

  useEffect(() => {
    if (token && id) {
      api.get(`/arvores/${id}`, {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`
        }
      }).then((response) => {
        setArvore(response.data.arvore)
      })
        .catch((err) => {
          setFlashMessage(err.response?.data?.message || 'Erro ao carregar árvore', 'error')
        })
    }
  }, [token, id]) // eslint-disable-line react-hooks/exhaustive-deps


  async function updateArvore(arvore) {

    let msgType = 'success'

    const formData = new FormData()

    // Adicionar novas imagens se houver (apenas File objects, não strings)
    if (arvore.images && Array.isArray(arvore.images) && arvore.images.length > 0) {
      const newImages = arvore.images.filter(img => img instanceof File)
      if (newImages.length > 0) {
        for (let i = 0; i < newImages.length; i++) {
          formData.append('images', newImages[i])
        }
      }
      // Se não há novas imagens (File objects), não adiciona nada ao formData
      // O backend manterá as imagens antigas
    }

    // Adicionar outros campos (exceto _id e images que já foram tratados)
    Object.keys(arvore).forEach((key) => {
      if (key !== 'images' && key !== '_id' && arvore[key] !== null && arvore[key] !== undefined && arvore[key] !== '') {
        // Converter para string se necessário
        const value = typeof arvore[key] === 'object' ? JSON.stringify(arvore[key]) : arvore[key]
        formData.append(key, value)
      }
    })

    try {
      const data = await api.patch(`/arvores/edit/${arvore._id}`, formData, {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`,
          'Content-Type': 'multipart/form-data'
        }
      }).then((response) => {
        msgType = 'success'
        return response.data
      }).catch((err) => {
        msgType = 'error'
        console.error('Erro ao atualizar árvore:', err)
        return err.response?.data || { message: 'Erro ao atualizar árvore. Verifique se todos os campos foram preenchidos corretamente.' }
      })

      if (data && data.message) {
        setFlashMessage(data.message, msgType)
        if (msgType !== 'error') {
          setTimeout(() => {
            history.push('/arvore/myarvore')
          }, 1500)
        }
      } else {
        setFlashMessage('Erro ao processar a atualização. Tente novamente.', 'error')
      }
    } catch (error) {
      console.error('Erro ao processar:', error)
      setFlashMessage('Erro ao processar a atualização. Tente novamente.', 'error')
    }

  }

  return (
    <section>
      <div className={styles.addarvore_header}>
        <h1>Editando a árvore: {arvore.species}</h1>
        <p>Depois da edição os dados serão atualizados no sistema</p>
      </div>
      {arvore.species && (
        <ArvoreForm handleSubmit={updateArvore} btnText="Atualizar" arvoreData={arvore} />
      )}
    </section>
  )
}

export default EditArvore

