import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useState, useEffect } from 'react'
import { useParams, Link, useHistory } from 'react-router-dom'
import { FaMapMarkerAlt, FaExclamationTriangle } from 'react-icons/fa'

import styles from '../Pet/PetDetails.module.css'

/* hooks */
import useFlashMessage from '../../../hooks/useFlashMessage'

function ArvoreDetails() {
    const [arvore, setArvore] = useState({})
    const { id } = useParams()
    const { setFlashMessage } = useFlashMessage()
    const [token] = useState(localStorage.getItem('token') || '')
    const [showAddressForm, setShowAddressForm] = useState(false)
    const [address, setAddress] = useState('')
    const history = useHistory()

    useEffect(() => {
        if (id) {
            api.get(`/arvores/${id}`)
                .then((response) => {
                    setArvore(response.data.arvore)
                })
                .catch((error) => {
                    setFlashMessage(
                        error.response?.data?.message || 'Erro ao carregar árvore',
                        'error'
                    )
                })
        }
    }, [id]) // eslint-disable-line react-hooks/exhaustive-deps

    function handleRequestClick() {
        setShowAddressForm(true)
    }

    async function requestTree() {
        if (!address.trim()) {
            setFlashMessage('Por favor, informe o endereço de entrega', 'error')
            return
        }

        let msgType = 'success'

        const data = await api
            .patch(`/arvores/request/${arvore._id}`, {
                deliveryAddress: address.trim()
            }, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
            .then((response) => {
                // Atualizar a árvore após solicitação bem-sucedida
                if (response.data.arvore) {
                    setArvore(response.data.arvore)
                }
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao solicitar árvore. Tente novamente.' }
            })

        // Mensagem melhorada para sucesso
        if (msgType === 'success') {
            const successMessage = `Solicitação enviada com sucesso. O doador ${arvore.user.name} foi notificado. Entre em contato pelo telefone ${arvore.user.phone} para combinar os detalhes da entrega.`
            setFlashMessage(successMessage, msgType)
            setShowAddressForm(false)
            setAddress('')

            // Redirecionar para a página de Minhas Solicitações após 2 segundos
            setTimeout(() => {
                history.push('/arvores/myrequests')
            }, 2000)
        } else {
            setFlashMessage(data.message, msgType)
        }
    }

    return (
        <>
            {arvore.species && (
                <section className={`${styles.pet_details_container} ${styles.arvore_details}`}>
                    <div className={styles.pet_details_header}>
                        <h1>Conhecendo a Árvore: {arvore.species}</h1>
                        <p>Se tiver interesse, solicite esta árvore para plantio</p>
                    </div>

                    <div className={styles.pet_images}>
                        {arvore.images &&
                            arvore.images.length > 0 &&
                            arvore.images.map((image, index) => (
                                <img
                                    src={`${getApiBase()}/images/arvores/${image}`}
                                    alt={arvore.species}
                                    key={index}
                                />
                            ))}
                    </div>

                    <div className={styles.pet_info_section}>
                        <p>
                            <span className="bold">Espécie:</span> {arvore.species}
                        </p>

                        <p>
                            <span className="bold">Nome Científico:</span> {arvore.scientificName}
                        </p>

                        <p>
                            <span className="bold">Origem:</span> {arvore.origin}
                        </p>

                        <p>
                            <span className="bold">Idade:</span> {arvore.age}
                        </p>

                        <p>
                            <span className="bold">Porte (Altura):</span> {arvore.height}
                        </p>

                        <p>
                            <span className="bold">Indicação para Fiação:</span> {arvore.allowsWiring ?
                                <span style={{ color: '#749666', fontWeight: 'bold' }}>Sim (Aceita fiação) ✅</span> :
                                <span style={{ color: '#e74c3c', fontWeight: 'bold' }}>Não (Não aceita fiação) ⚠️</span>
                            }
                        </p>

                        <p>
                            <span className="bold">Localização:</span> {arvore.location}
                        </p>

                        <p>
                            <span className="bold">Descrição:</span> {arvore.description}
                        </p>

                        <p>
                            <span className="bold">Quantidade disponível:</span> {arvore.quantity}
                        </p>
                    </div>

                    {token ? (
                        arvore.available && arvore.quantity > 0 ? (
                            <>
                                {!showAddressForm ? (
                                    <button onClick={handleRequestClick} className={styles.action_button}>
                                        Solicitar Árvore
                                    </button>
                                ) : (
                                    <div className={styles.address_form_container}>
                                        <div className={styles.form_header}>
                                            <FaMapMarkerAlt className={styles.form_icon} />
                                            <h3>Informe o Endereço de Entrega</h3>
                                            <p>Digite o endereço completo onde deseja receber a árvore</p>
                                        </div>
                                        <textarea
                                            value={address}
                                            onChange={(e) => setAddress(e.target.value)}
                                            placeholder="Exemplo: Rua das Flores, 123, Bairro Centro, Cidade - Estado, CEP 12345-678"
                                            className={styles.address_textarea}
                                        />
                                        <div className={styles.form_buttons}>
                                            <button
                                                onClick={requestTree}
                                                className={styles.submit_button}
                                            >
                                                Enviar Solicitação
                                            </button>
                                            <button
                                                onClick={() => {
                                                    setShowAddressForm(false)
                                                    setAddress('')
                                                }}
                                                className={styles.cancel_button}
                                            >
                                                Cancelar
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </>
                        ) : (
                            <div className={styles.status_message}>
                                <FaExclamationTriangle className={styles.status_icon} />
                                <div>
                                    <h3>Árvore Indisponível</h3>
                                    <p>Esta árvore não está mais disponível para solicitação no momento.</p>
                                </div>
                            </div>
                        )
                    ) : (
                        <div className={styles.login_prompt}>
                            <p>
                                Você precisa <Link to="/register">criar uma conta</Link> para solicitar a árvore
                            </p>
                        </div>
                    )}
                </section>
            )}
        </>
    )
}

export default ArvoreDetails

