import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'
import { useState, useEffect, useCallback } from 'react'
import { Link } from 'react-router-dom'
import styles from './ManageUsers.module.css'
import useFlashMessage from '../../../hooks/useFlashMessage'
import RoundedImage from '../../layout/RoundedImage'

function ManageUsers() {
    const [users, setUsers] = useState([])
    const [token] = useState(localStorage.getItem('token') || '')
    const { setFlashMessage } = useFlashMessage()

    const loadUsers = useCallback(() => {
        if (token) {
            api.get('/users/admin/all', {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
                .then((response) => {
                    setUsers(response.data.users || [])
                })
                .catch((err) => {
                    console.error('Erro ao carregar usuários:', err)
                })
        }
    }, [token])

    useEffect(() => {
        loadUsers()
    }, [loadUsers])

    async function removeUser(id) {
        let msgType = 'success'

        const data = await api
            .delete(`/users/admin/delete/${id}`, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`,
                },
            })
            .then((response) => {
                const updatedUsers = users.filter((user) => user._id !== id)
                setUsers(updatedUsers)
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response.data
            })

        setFlashMessage(data.message, msgType)
    }

    async function toggleTreeManagement(id) {
        let msgType = 'success'

        const data = await api
            .patch(`/users/admin/toggle-tree/${id}`, {}, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`,
                },
            })
            .then((response) => {
                const updatedUsers = users.map((u) => {
                    if (u._id === id) {
                        return { ...u, canManageTrees: response.data.canManageTrees }
                    }
                    return u
                })
                setUsers(updatedUsers)
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao atualizar permissão.' }
            })

        setFlashMessage(data.message, msgType)
    }

    return (
        <section className={styles.manage_users_section}>
            <div className={styles.header}>
                <h1>Gestão de Usuários (SAMA)</h1>
                <Link to="/admin/users/create" className={styles.add_btn}>Criar Novo Usuário</Link>
            </div>
            <p className={styles.description}>
                Aqui você visualiza e gerencia os usuários que <strong>você</strong> cadastrou no sistema.
            </p>

            <div className={styles.users_container}>
                {users.length > 0 &&
                    users.map((user) => (
                        <div className={styles.user_row} key={user._id}>
                            <RoundedImage
                                src={user.image ? `${getApiBase()}/images/users/${user.image}` : `https://ui-avatars.com/api/?name=${user.name}`}
                                alt={user.name}
                                width="px75"
                            />
                            <div className={styles.user_info}>
                                <span className={styles.user_name}>{user.name}</span>
                                <span className={styles.user_email}>{user.email}</span>
                                <div className={styles.badges}>
                                    {user.isAdmin && <span className={styles.admin_badge}>Admin</span>}
                                    <span className={styles.type_badge}>{user.userType}</span>
                                </div>
                            </div>
                            <div className={styles.actions}>
                                <button
                                    className={user.canManageTrees ? styles.deactivate_btn : styles.activate_btn}
                                    onClick={() => toggleTreeManagement(user._id)}
                                    title={user.canManageTrees ? "Revogar permissão de gerir árvores" : "Autorizar este usuário a cadastrar árvores"}
                                >
                                    {user.canManageTrees ? 'Desativar Árvores' : 'Ativar Árvores'}
                                </button>
                                <button
                                    className={styles.delete_btn}
                                    onClick={() => removeUser(user._id)}
                                >
                                    Excluir
                                </button>
                            </div>
                        </div>
                    ))}
                {users.length === 0 && <p>Nenhum usuário cadastrado por você ainda.</p>}
            </div>
        </section>
    )
}

export default ManageUsers
