import { useState, useContext } from 'react'

import Input from '../../form/Input'

import { Link } from 'react-router-dom'

import { FaUser, FaPhone, FaEnvelope, FaLock, FaCheck } from "react-icons/fa"

import styles from '../../form/Form.module.css'

/* contxts */

import { Context } from '../../../context/UserContext'

function Register() {

    const [user, setUser] = useState({})
    const [loading, setLoading] = useState(false)
    const { register } = useContext(Context)

    function maskCPF(value) {
        return value
            .replace(/\D/g, '')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d{1,2})/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskCNPJ(value) {
        return value
            .replace(/\D/g, '')
            .replace(/(\d{2})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1/$2')
            .replace(/(\d{4})(\d)/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskPhone(value) {
        return value
            .replace(/\D/g, '')
            .replace(/(\d{2})(\d)/, '($1) $2')
            .replace(/(\d{5})(\d)/, '$1-$2')
            .replace(/(-\d{4})\d+?$/, '$1')
    }

    function handleChange(e) {
        let value = e.target.value
        const name = e.target.name

        if (name === 'cpf_cnpj') {
            value = user.userType === 'Instituto' ? maskCNPJ(value) : maskCPF(value)
        } else if (name === 'phone') {
            value = maskPhone(value)
        }

        setUser({ ...user, [name]: value })
    }


    async function handleSubmit(e) {
        e.preventDefault()

        if (loading) return

        // Basic Email Validation
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
        if (!emailRegex.test(user.email)) {
            // Context normally handles flash messages, but let's check if we can prevent submission
            // For now, let the context handler deal with backend response if invalid
        }

        setLoading(true)
        await register(user)
        setLoading(false)
    }


    return (
        <section className={styles.form_container}>
            <div className={styles.form_header}>
                <h1>Bem-vindo à Sama</h1>
                <h2>Plataforma de adoção de pets e solicitações de árvores</h2>
            </div>

            <form onSubmit={handleSubmit}>
                <div className={styles.form_control}>
                    <label>Tipo de Usuário:</label>
                    <select
                        name="userType"
                        onChange={handleChange}
                        value={user.userType || 'Pessoa Física'}
                        className={styles.select_input}
                    >
                        <option value="Pessoa Física">Pessoa Física</option>
                        <option value="Instituto">Instituto / ONG</option>
                    </select>
                </div>

                {user.userType === 'Instituto' && (
                    <Input
                        text={<><FaUser /> Nome do Instituto</>}
                        type="text"
                        name="instituteName"
                        placeholder="Digite o nome da sua ONG ou Instituto"
                        handleOnChange={handleChange}
                        value={user.instituteName || ''}
                    />
                )}

                <Input
                    text={<><FaCheck /> {user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}</>}
                    type="text"
                    name="cpf_cnpj"
                    placeholder={`Digite o seu ${user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}`}
                    handleOnChange={handleChange}
                    value={user.cpf_cnpj || ''}
                />

                <Input
                    text={<><FaUser /> Nome</>}
                    type="text"
                    name="name"
                    placeholder="Digite o seu nome completo"
                    handleOnChange={handleChange}
                    value={user.name || ''}
                />

                <Input
                    text={<><FaPhone /> Telefone</>}
                    type="text"
                    name="phone"
                    placeholder="Digite o seu Telefone"
                    handleOnChange={handleChange}
                    value={user.phone || ''}
                />

                <Input
                    text={<><FaEnvelope /> E-mail</>}
                    type="email"
                    name="email"
                    placeholder="Digite o seu e-mail"
                    handleOnChange={handleChange}
                    value={user.email || ''}
                />

                <Input
                    text={<><FaLock /> Senha</>}
                    type="password"
                    name="password"
                    placeholder="Digite a sua Senha"
                    handleOnChange={handleChange}
                    value={user.password || ''}
                />

                <Input
                    text={<><FaCheck /> Confirmação de Senha</>}
                    type="password"
                    name="confirmpassword"
                    placeholder="Confirme a sua Senha"
                    handleOnChange={handleChange}
                    value={user.confirmpassword || ''}
                />

                <input type="submit" value={loading ? "Cadastrando..." : "Cadastrar"} disabled={loading} />
            </form>

            <p>
                Já tem conta? <Link to="/login">Clique aqui.</Link>
            </p>
        </section>
    )
}

export default Register
