import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'
import { useEffect, useState, useContext, useCallback } from 'react'
import { Link } from 'react-router-dom'
import RoundedImage from '../../layout/RoundedImage'
import useFlashMessage from '../../../hooks/useFlashMessage'
import { Context } from '../../../context/UserContext'
import styles from './MyPets.module.css'

function MyPets() {
  const [pets, setPets] = useState([])
  const [token] = useState(localStorage.getItem('token') || '')
  const { setFlashMessage } = useFlashMessage()
  const { user } = useContext(Context)
  const [adminMessages, setAdminMessages] = useState({})

  const loadPets = useCallback(() => {
    if (token) {
      api.get('/pets/mypets', {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`
        }
      })
        .then((response) => {
          const myPets = response.data.pets || []
          const sortedPets = myPets.sort((a, b) => {
            const aHasRequest = a.adopter && a.adopter._id
            const bHasRequest = b.adopter && b.adopter._id

            if (aHasRequest && bHasRequest) {
              const aDate = a.adopter.createdAt || a.adopter.updatedAt || a.updatedAt || a.createdAt || new Date(0)
              const bDate = b.adopter.createdAt || b.adopter.updatedAt || b.updatedAt || b.createdAt || new Date(0)
              return new Date(bDate) - new Date(aDate)
            }
            if (aHasRequest && !bHasRequest) return -1
            if (!aHasRequest && bHasRequest) return 1
            return 0
          })
          setPets(sortedPets)
        })
        .catch((err) => {
          console.error('Erro ao carregar pets:', err)
          setFlashMessage(err.response?.data?.message || 'Erro ao carregar pets', 'error')
        })
    }
  }, [token]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    loadPets()
  }, [loadPets])

  async function removePet(id) {
    try {
      const response = await api.delete(`/pets/${id}`, {
        headers: { Authorization: `Bearer ${JSON.parse(token)}` },
      })
      setPets(pets.filter((pet) => pet._id !== id))
      setFlashMessage(response.data.message, 'success')
    } catch (err) {
      setFlashMessage(err.response.data.message, 'error')
    }
  }

  async function updateStatus(id, newStatus) {
    try {
      // Mapeia os status para as rotas corretas no backend
      let endpoint = ''
      let body = {}
      if (newStatus === 'Aprovado') {
        endpoint = `/pets/conclude/${id}`
        body = { message: adminMessages[id] || '' }
      } else if (newStatus === 'Recusado' || newStatus === 'Cancelado') {
        endpoint = `/pets/cancel/${id}`
        body = { message: adminMessages[id] || '' }
      } else {
        // Para status intermediários (ex: 'Em análise'), usa rota dedicada
        endpoint = `/pets/status/${id}`
        body = { status: newStatus, message: adminMessages[id] || '' }
      }
      const response = await api.patch(endpoint, body, {
        headers: { Authorization: `Bearer ${JSON.parse(token)}` }
      })
      setFlashMessage(response.data.message, 'success')
      setAdminMessages(prev => ({ ...prev, [id]: '' })) // Limpar após sucesso
      loadPets()
    } catch (err) {
      setFlashMessage(err.response?.data?.message || 'Erro ao atualizar status', 'error')
    }
  }

  async function concludeAdoption(id) {
    try {
      const response = await api.patch(`/pets/conclude/${id}`, {}, {
        headers: { Authorization: `Bearer ${JSON.parse(token)}` },
      })
      setFlashMessage(response.data.message, 'success')
      loadPets()
    } catch (err) {
      setFlashMessage(err.response?.data?.message || 'Erro ao concluir adoção', 'error')
    }
  }

  async function cancelAdoption(id) {
    try {
      const response = await api.patch(`/pets/cancel/${id}`, {}, {
        headers: { Authorization: `Bearer ${JSON.parse(token)}` },
      })
      setFlashMessage(response.data.message, 'success')
      loadPets()
    } catch (err) {
      setFlashMessage(err.response?.data?.message || 'Erro ao cancelar solicitação', 'error')
    }
  }

  return (
    <section className={styles.my_pets_section}>
      <div className={styles.petlist_header}>
        <h1 className={styles.klinic_title}>{(user?.isAdmin || user?.canManageTrees) ? 'Gerenciar Pets' : 'Meus Pets'}</h1>
        {pets.length > 0 && <p style={{ fontSize: '1.1rem', color: '#000', marginTop: '5px' }}>{pets.length} pets cadastrados</p>}
        <div className={styles.header_actions}>
          <Link to="/pet/add" className={styles.addBtn}>Cadastrar Pet</Link>
        </div>
      </div>

      <div className={styles.petlist_container}>
        {pets.length > 0 &&
          pets.map((pet) => {
            const isOwner = user?.isAdmin || user?.canManageTrees || (pet.user && (pet.user._id === user?._id || pet.user._id === user?._id?.toString()))

            return (
              <div className={styles.petlist_row} key={pet._id}>
                {pet.images && pet.images.length > 0 && pet.images[0] ? (
                  <RoundedImage
                    src={`${getApiBase()}/images/pets/${pet.images[0]}`}
                    alt={pet.name}
                    width="px75"
                  />
                ) : (
                  <div className={styles.no_image_placeholder}>
                    <span>Sem imagem</span>
                  </div>
                )}

                <div className={styles.pet_info_container}>
                  <span className={styles.pet_name}>{pet.name}</span>

                  {pet.adopter && (
                    <div className={styles.status_wrapper_admin}>
                      <span className={`${styles.status_badge_mini} ${styles['status_' + pet.adopter.status?.toLowerCase().replace(/\s/g, '_')] || ''}`}>
                        Status: {pet.adopter.status}
                      </span>
                    </div>
                  )}

                  <div className={styles.pet_details}>
                    <div className={styles.info_row}>
                      <div className={styles.info_item}>
                        <span className={styles.info_label}>Raça/Tipo</span>
                        <span className={styles.info_value}>{pet.breed} ({pet.type})</span>
                      </div>
                    </div>
                    <div className={styles.info_row}>
                      <div className={styles.info_item}>
                        <span className={styles.info_label}>Peso / Idade</span>
                        <span className={styles.info_value}>{pet.weight}kg / {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} ${pet.age == 1 ? 'ano' : 'anos'}`}</span>
                      </div>
                    </div>
                  </div>

                  {pet.adopter && (isOwner || user?.isAdmin) && (
                    <div className={styles.requester_info}>
                      <div className={styles.requester_header}>
                        <span className={styles.requester_title}>Pessoa solicitando</span>
                      </div>
                      <div className={styles.requester_details}>
                        <div className={styles.info_row}>
                          <div className={styles.info_item}>
                            <span className={styles.info_label}>Nome</span>
                            <span className={styles.info_value}>{pet.adopter.name}</span>
                          </div>
                        </div>
                        {pet.adopter.phone && (
                          <div className={styles.info_row}>
                            <div className={styles.info_item}>
                              <span className={styles.info_label}>Telefone</span>
                              <span className={styles.info_value}>{pet.adopter.phone}</span>
                            </div>
                          </div>
                        )}
                        {pet.adopter.deliveryAddress && (
                          <div className={styles.delivery_address}>
                            <div className={styles.delivery_header}>
                              <span className={styles.delivery_icon}>📍</span>
                              <span className={styles.delivery_label}>Local de Encontro</span>
                            </div>
                            <p className={styles.address_text}>{pet.adopter.deliveryAddress}</p>
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                </div>

                <div className={styles.actions}>
                  {(isOwner || user?.isAdmin || user?.canManageTrees) && (
                    <>
                      {pet.adopter && pet.available && (
                        <div className={styles.admin_controls}>
                          <div className={styles.message_control}>
                            <textarea
                              placeholder="Envie um recado para o adotante (ex: local de encontro, horário...)"
                              value={adminMessages[pet._id] || ''}
                              onChange={(e) => setAdminMessages(prev => ({ ...prev, [pet._id]: e.target.value }))}
                              className={styles.admin_textarea}
                            />
                          </div>
                          <div className={styles.button_group}>
                            <button className={`${styles.analysis_btn} ${pet.adopter.status === 'Em análise' ? styles.active_status : ''}`} onClick={() => updateStatus(pet._id, 'Em análise')}>
                              ⏳ Em análise
                            </button>
                            <button className={`${styles.accept_btn} ${pet.adopter.status === 'Aprovado' ? styles.active_status : ''}`} onClick={() => updateStatus(pet._id, 'Aprovado')}>
                              ✅ Aprovar
                            </button>
                            <button className={`${styles.reject_btn} ${pet.adopter.status === 'Recusado' ? styles.active_status : ''}`} onClick={() => updateStatus(pet._id, 'Recusado')}>
                              ❌ Recusar
                            </button>
                            <button
                              className={styles.delete_request_btn}
                              onClick={() => cancelAdoption(pet._id)}
                              title="Remover solicitante e limpar status"
                            >
                              🗑️ Apagar Solicitação
                            </button>
                          </div>
                          {pet.adopter.status === 'Aprovado' && (
                            <button className={styles.conclude_btn} onClick={() => concludeAdoption(pet._id)}>
                              Finalizar
                            </button>
                          )}
                        </div>
                      )}
                      {!pet.available && (
                        <div className={styles.concluded_badge}>
                          <span className={styles.check_icon}>✓</span>
                          Adoção Concluída
                        </div>
                      )}
                      <Link to={`/pet/edit/${pet._id}`} className={styles.edit_btn}>Editar</Link>
                      <button className={styles.delete_btn} onClick={() => removePet(pet._id)}>Excluir</button>
                    </>
                  )}
                </div>
              </div>
            )
          })}

        {pets.length === 0 && (
          <p className={styles.empty_list}>🐾 Não há pets cadastrados ainda.</p>
        )}
      </div>
    </section>
  )
}

export default MyPets
