        const params = new URLSearchParams(location.search)
        const search = params.get('search')
        const breed = params.get('breed')
        const gender = params.get('gender')

        let url = '/pets'
        const queryParams = []
        if (search) queryParams.push(`search=${encodeURIComponent(search)}`)
        if (breed) queryParams.push(`breed=${encodeURIComponent(breed)}`)
        if (gender) queryParams.push(`gender=${encodeURIComponent(gender)}`)

        if (queryParams.length > 0) {
            url += '?' + queryParams.join('&')
        }

        api.get(url).then((response) => {
            const allPets = response.data.pets || []

            // Separar pets disponíveis e adotados
            const available = allPets.filter(pet => pet.available !== false)
            const adopted = allPets.filter(pet => pet.available === false)

            setAvailablePets(available)
            setAdoptedPets(adopted)
        }).catch((error) => {
            console.error('Erro ao buscar pets:', error)
            setAvailablePets([])
            setAdoptedPets([])
        })
