import { useState } from 'react'
import api from '../../../utils/api'
import { useHistory } from 'react-router-dom'
import Input from '../../form/Input'
import styles from '../../form/Form.module.css'
import useFlashMessage from '../../../hooks/useFlashMessage'
import { FaUser, FaPhone, FaEnvelope, FaLock, FaCheck } from "react-icons/fa"

function CreateUserAdmin() {
    const [user, setUser] = useState({ userType: 'Pessoa Física', isAdmin: false })
    const [loading, setLoading] = useState(false)
    const { setFlashMessage } = useFlashMessage()
    const history = useHistory()
    const [token] = useState(localStorage.getItem('token') || '')

    function maskCPF(value) {
        return value.replace(/\D/g, '').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d{1,2})/, '$1-$2').replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskCNPJ(value) {
        return value.replace(/\D/g, '').replace(/(\d{2})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1.$2').replace(/(\d{3})(\d)/, '$1/$2').replace(/(\d{4})(\d)/, '$1-$2').replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskPhone(value) {
        return value.replace(/\D/g, '').replace(/(\d{2})(\d)/, '($1) $2').replace(/(\d{5})(\d)/, '$1-$2').replace(/(-\d{4})\d+?$/, '$1')
    }

    function handleChange(e) {
        let value = e.target.type === 'checkbox' ? e.target.checked : e.target.value
        const name = e.target.name

        if (name === 'cpf_cnpj') {
            value = user.userType === 'Instituto' ? maskCNPJ(value) : maskCPF(value)
        } else if (name === 'phone') {
            value = maskPhone(value)
        }

        setUser({ ...user, [name]: value })
    }

    async function handleSubmit(e) {
        e.preventDefault()
        setLoading(true)

        try {
            const response = await api.post('/users/admin/create', user, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
            setFlashMessage(response.data.message, 'success')
            history.push('/admin/users')
        } catch (error) {
            setFlashMessage(error.response?.data?.message || 'Erro ao criar usuário', 'error')
        } finally {
            setLoading(false)
        }
    }

    return (
        <section className={styles.form_container}>
            <div className={styles.form_header}>
                <h1>Cadastrar Usuário SAMA</h1>
                <p>Crie um novo usuário que terá acesso administrativo (Sub-Admin).</p>
            </div>
            <form onSubmit={handleSubmit}>
                <div className={styles.form_control}>
                    <label>Tipo de Usuário:</label>
                    <select
                        name="userType"
                        onChange={handleChange}
                        value={user.userType}
                        className={styles.select_input}
                    >
                        <option value="Pessoa Física">Pessoa Física</option>
                        <option value="Instituto">Instituto / ONG</option>
                    </select>
                </div>

                <div className={styles.form_control_checkbox} style={{ display: 'flex', alignItems: 'center', marginBottom: '1em' }}>
                    <input
                        type="checkbox"
                        name="isAdmin"
                        onChange={handleChange}
                        checked={user.isAdmin}
                        id="isAdmin"
                        style={{ width: 'auto', marginRight: '10px' }}
                    />
                    <label htmlFor="isAdmin">Dar acesso de Administrador?</label>
                </div>

                {user.userType === 'Instituto' && (
                    <Input
                        text={<><FaUser /> Nome do Instituto</>}
                        type="text"
                        name="instituteName"
                        placeholder="Digite o nome da ONG ou Instituto"
                        handleOnChange={handleChange}
                        value={user.instituteName || ''}
                    />
                )}

                <Input
                    text={<><FaCheck /> {user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}</>}
                    type="text"
                    name="cpf_cnpj"
                    placeholder={`Digite o ${user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}`}
                    handleOnChange={handleChange}
                    value={user.cpf_cnpj || ''}
                />

                <Input
                    text={<><FaUser /> Nome Completo</>}
                    type="text"
                    name="name"
                    placeholder="Digite o nome completo"
                    handleOnChange={handleChange}
                    value={user.name || ''}
                />

                <Input
                    text={<><FaPhone /> Telefone</>}
                    type="text"
                    name="phone"
                    placeholder="Digite o Telefone"
                    handleOnChange={handleChange}
                    value={user.phone || ''}
                />

                <Input
                    text={<><FaEnvelope /> E-mail</>}
                    type="email"
                    name="email"
                    placeholder="Digite o e-mail"
                    handleOnChange={handleChange}
                    value={user.email || ''}
                />

                <Input
                    text={<><FaLock /> Senha Provisória</>}
                    type="password"
                    name="password"
                    placeholder="Digite uma senha"
                    handleOnChange={handleChange}
                    value={user.password || ''}
                />

                <input type="submit" value={loading ? "Criando..." : "Cadastrar Usuário"} disabled={loading} />
            </form>
        </section>
    )
}

export default CreateUserAdmin
