import { useEffect, useState } from 'react'
import { useHistory } from 'react-router-dom'
import api from '../utils/api'
import useFlashMessage from './useFlashMessage'

export default function useAuth() {
    const [authenticated, setAuthenticated] = useState(false)
    const [user, setUser] = useState({})
    const { setFlashMessage } = useFlashMessage()
    const history = useHistory()

    useEffect(() => {
        const token = localStorage.getItem('token')

        if (token) {
            api.defaults.headers.Authorization = `Bearer ${JSON.parse(token)}`
            setAuthenticated(true)
            checkUser()
        }
    }, [])

    async function checkUser() {
        try {
            const response = await api.get('/users/checkuser')
            setUser(response.data || {})
        } catch (error) {
            console.error('Erro ao verificar usuário:', error)
            setUser({})
        }
    }

    async function authUser(data) {
        setAuthenticated(true)
        localStorage.setItem('token', JSON.stringify(data.token))
        api.defaults.headers.Authorization = `Bearer ${data.token}`
        await checkUser()
        history.push('/')
    }

    async function register(user) {
        let msgText = 'Cadastro realizado com sucesso!!'
        let msgType = 'success'

        try {
            const response = await api.post('/users/register', user)

            msgText = response.data?.message || 'Cadastro realizado com sucesso!!'
            msgType = 'success'

            await authUser(response.data)
        } catch (error) {
            msgText = error.response?.data?.message || 'Erro ao cadastrar.'
            msgType = 'error'
        }

        setFlashMessage(msgText, msgType)
    }

    async function login(user) {
        let msgText = 'Login realizado com sucesso!'
        let msgType = 'success'

        try {
            const response = await api.post('/users/login', user)
            const data = response.data

            await authUser(data)
            setFlashMessage(msgText, msgType)
        } catch (error) {
            msgText = error.response?.data?.message || 'Erro ao fazer login.'
            msgType = 'error'
            setFlashMessage(msgText, msgType)
        }
    }

    function logout() {
        const msgText = 'Logout realizado com sucesso!'
        const msgType = 'success'

        setAuthenticated(false)
        setUser({})
        localStorage.removeItem('token')
        api.defaults.headers.Authorization = undefined
        history.push('/')

        setFlashMessage(msgText, msgType)
    }

    return { authenticated, user, register, logout, login }
}
