import { getApiBase } from './api'
import jsPDF from 'jspdf'
import 'jspdf-autotable'

// Helper to load image and return params
const loadImage = (url) => {
    return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Image load timeout')), 8000)

        const img = new Image()
        img.setAttribute('crossOrigin', 'anonymous')
        img.onload = () => {
            clearTimeout(timeout)
            resolve(img)
        }
        img.onerror = (error) => {
            clearTimeout(timeout)
            reject(error)
        }
        img.src = url
    })
}

// Convert loaded image element to Base64 (JPEG)
const imageToBase64 = (img) => {
    const canvas = document.createElement('canvas')
    canvas.width = img.width
    canvas.height = img.height
    const ctx = canvas.getContext('2d')
    ctx.drawImage(img, 0, 0)
    return canvas.toDataURL('image/jpeg')
}

// Original helper for direct URL to base64 (used for logo)
const getBase64ImageFromURL = async (url) => {
    const img = await loadImage(url)
    return imageToBase64(img)
}

export const generateTreePDF = async (arvores, logoUrl) => {
    try {
        const doc = new jsPDF()
        const pageWidth = doc.internal.pageSize.getWidth() // 210
        const pageHeight = doc.internal.pageSize.getHeight() // 297

        // --- Header Configuration (Only for First Page) ---
        const addHeader = async (doc) => {
            // White background for header area
            doc.setFillColor(255, 255, 255)
            doc.rect(0, 0, pageWidth, 40, 'F')

            if (logoUrl) {
                try {
                    const logoBase64 = await getBase64ImageFromURL(logoUrl)
                    // Draw white background behind logo specifically
                    doc.setFillColor(255, 255, 255)
                    doc.rect(10, 5, 25, 25, 'F')
                    doc.addImage(logoBase64, 'PNG', 10, 5, 25, 25)
                } catch (e) {
                    console.log('Logo load failed', e)
                }
            }

            doc.setTextColor(116, 150, 102) // Green Text
            doc.setFontSize(18)
            doc.setFont('helvetica', 'bold')
            doc.text('CATÁLOGO DE PLANTIO', 40, 15)

            doc.setFontSize(10)
            doc.setFont('helvetica', 'normal')
            doc.setTextColor(80, 80, 80)
            doc.text('Secretaria Municipal de Agricultura e Meio Ambiente - Garça/SP', 40, 22)

            // Green line separator
            doc.setDrawColor(116, 150, 102)
            doc.setLineWidth(0.5)
            doc.line(10, 32, pageWidth - 10, 32)

            // Date on first page
            doc.setTextColor(100, 100, 100)
            doc.setFontSize(8)
            doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, pageWidth - 10, 8, { align: 'right' })
        }

        // Render Header ONLY on first page
        await addHeader(doc)

        let yOffset = 45 // Start below header on Page 1
        const margin = 10
        const colGap = 5
        const rowGap = 5

        // Grid Setup: 2 Cols
        const cardWidth = (pageWidth - (margin * 2) - colGap) / 2
        const cardHeight = 85

        let colIndex = 0

        for (let i = 0; i < arvores.length; i++) {
            const arvore = arvores[i]
            if (!arvore) continue;

            // Calculate Position
            const currentX = margin + (colIndex * (cardWidth + colGap))

            // Check if we fit in the current page vertically
            // pageHeight - margin bottom (10)
            if (yOffset + cardHeight > pageHeight - 10) {
                doc.addPage()
                yOffset = 20 // Start higher on subsequent pages
                colIndex = 0
            }

            const currentY = yOffset

            // Card Container line
            doc.setDrawColor(200, 200, 200)
            doc.setLineWidth(0.1)
            doc.setFillColor(255, 255, 255)
            doc.roundedRect(currentX, currentY, cardWidth, cardHeight, 2, 2, 'S')

            // Inner Padding
            const p = 4

            // Image Box (Left side) 35x35
            const imgBoxW = 35
            const imgBoxH = 35
            const imgX = currentX + p
            const imgY = currentY + p

            let imageProcessed = false
            if (arvore.images && arvore.images.length > 0) {
                try {
                    const imgUrl = `${getApiBase()}/images/arvores/${arvore.images[0]}`
                    const imgElem = await loadImage(imgUrl)
                    const base64Img = imageToBase64(imgElem)

                    // Aspect Ratio Logic
                    const ratio = imgElem.width / imgElem.height
                    let drawW = imgBoxW
                    let drawH = imgBoxH
                    let drawX = imgX
                    let drawY = imgY

                    // If wider than box
                    if (ratio > 1) {
                        drawH = imgBoxW / ratio
                        drawY = imgY + (imgBoxH - drawH) / 2
                    } else {
                        // Taller than box
                        drawW = imgBoxH * ratio
                        drawX = imgX + (imgBoxW - drawW) / 2
                    }

                    doc.addImage(base64Img, 'JPEG', drawX, drawY, drawW, drawH)
                    imageProcessed = true

                    // Optional: Draw a subtle border around format
                    doc.setDrawColor(240, 240, 240)
                    doc.rect(imgX, imgY, imgBoxW, imgBoxH)

                } catch (e) {
                    console.log('Tree image load failed', e)
                }
            }

            if (!imageProcessed) {
                doc.setFillColor(245, 245, 245)
                doc.rect(imgX, imgY, imgBoxW, imgBoxH, 'F')
                doc.setFontSize(6)
                doc.setTextColor(150, 150, 150)
                doc.text('Sem img', imgX + 5, imgY + 15)
            }

            // Title
            doc.setFontSize(10)
            doc.setFont('helvetica', 'bold')
            doc.setTextColor(116, 150, 102) // Green Title
            const titleX = imgX + imgBoxW + 4
            const speciesName = arvore.species || 'Espécie'

            // Wrap title if long
            const splitTitle = doc.splitTextToSize(speciesName.toUpperCase(), cardWidth - imgBoxW - p - 6)
            doc.text(splitTitle, titleX, imgY + 4)

            // Details (Right of image)
            doc.setFontSize(8)
            doc.setFont('helvetica', 'normal')
            doc.setTextColor(60, 60, 60)

            // Roughly adjust text Y based on title height
            let textY = imgY + (splitTitle.length * 4) + 6
            const lineHeight = 4

            const addInfo = (label, val) => {
                if (val) {
                    doc.setFont('helvetica', 'bold')
                    doc.text(`${label}:`, titleX, textY)
                    doc.setFont('helvetica', 'normal')
                    doc.text(`${val}`, titleX + 16, textY)
                    textY += lineHeight
                }
            }

            addInfo('Científico', arvore.scientificName ? arvore.scientificName.substring(0, 18) : '-')
            addInfo('Porte', arvore.height)
            addInfo('Origem', arvore.origin)
            addInfo('Idade', arvore.age)

            const wiringText = arvore.allowsWiring ? 'Permitida' : 'Não Rec.'
            addInfo('Fiação', wiringText)

            // Description Area
            // Start below image or text, whichever is lower
            let descY = Math.max(imgY + imgBoxH, textY) + 5

            // Ensure we don't go too low inside the card before printing description
            // Max description height: cardHeight - (descY - currentY) - footer(10)

            doc.setFontSize(7)
            doc.setFont('helvetica', 'bold')
            doc.text('Descrição:', currentX + p, descY)

            doc.setFont('helvetica', 'normal')
            doc.setTextColor(90, 90, 90)
            const descText = arvore.description || 'Sem descrição cadastrada.'

            // Split text to fit width
            const splitDesc = doc.splitTextToSize(descText, cardWidth - (p * 2))

            // Calculate how many lines fit
            // Bottom limit Y = currentY + cardHeight - 8 (for footer)
            const bottomLimit = currentY + cardHeight - 8
            const availableHeight = bottomLimit - (descY + 4)
            const linesThatFit = Math.floor(availableHeight / 3) // roughly 3 units per line at size 7

            doc.text(splitDesc.slice(0, Math.max(1, linesThatFit)), currentX + p, descY + 4)

            // Location at Bottom
            const bottomY = currentY + cardHeight - 4
            doc.setFontSize(7)
            doc.setTextColor(150, 150, 150)
            doc.text(`Local: ${arvore.location || '-'}`, currentX + p, bottomY)

            // Update Grid Column/Row Logic
            colIndex++
            if (colIndex >= 2) {
                colIndex = 0
                yOffset += cardHeight + rowGap
            }
        }

        // Page Numbers Footer
        const totalPages = doc.internal.getNumberOfPages()
        for (let j = 1; j <= totalPages; j++) {
            doc.setPage(j)
            doc.setFontSize(8)
            doc.setTextColor(150, 150, 150)
            doc.text(`${j} / ${totalPages}`, pageWidth - 15, pageHeight - 10, { align: 'right' })
        }

        doc.save('Catalogo_Plantio_SAMA.pdf')
    } catch (err) {
        console.error('Critical Error generating PDF:', err)
        throw err
    }
}
