import axios from 'axios'

// Usa /api quando config.js define __API_BASE__ (deploy no api-semit)
const baseURL = (typeof window !== 'undefined' && window.__API_BASE__)
    ? `${window.location.origin}${window.__API_BASE__}`
    : 'http://localhost:5000'

// Retorna a base URL da API (sem barra final) para montar URLs de imagens etc.
export function getApiBase() {
    return baseURL.replace(/\/+$/, '')
}

export default axios.create({
    baseURL,
})