import { BrowserRouter as Router, Switch, Route } from 'react-router-dom'

/* components */
import Navbar from './components/layout/Navbar'
import Footer from './components/layout/Footer'
import Container from './components/layout/Container'
import Message from './components/layout/Message'

/* pages */
import Login from './components/pages/Auth/login'
import Register from './components/pages/Auth/Register'
import Home from './components/pages/User/Home'
import AdoptionHome from './components/pages/Pet/AdoptionHome'
import Profile from './components/pages/User/Profile'
import MyPets from './components/pages/Pet/MyPets'
import AddPet from './components/pages/Pet/AddPet'
import EditPet from './components/pages/Pet/EditPet'
import PetDetails from './components/pages/Pet/PetDetails'
import MyAdoptions from './components/pages/Pet/MyAdoptions'
import MyArvore from './components/pages/Arvore/MyArvore'
import AddArvore from './components/pages/Arvore/AddArvore'
import EditArvore from './components/pages/Arvore/EditArvore'
import MyRequests from './components/pages/Arvore/MyRequests'
import TreesHome from './components/pages/Arvore/TreesHome'
import ArvoreDetails from './components/pages/Arvore/ArvoreDetails'
import About from './components/pages/About/About'
import Denounce from './components/pages/Denounce/Denounce'
import Castracao from './components/pages/Castracao/Castracao'
import Sama from './components/pages/Arvore/Sama'
import Zoologico from './components/pages/Zoologico/Zoologico'

import ManageUsers from './components/pages/Admin/ManageUsers'
import CreateUserAdmin from './components/pages/Admin/CreateUserAdmin'

import Functionality from './components/pages/Functionality/Functionality'
import ScrollToTop from './components/layout/ScrollToTop'

/* context */
import { UserProvider } from './context/UserContext'

function App() {
  return (
    <Router>
      <UserProvider>
        <Navbar />
        <Message />
        <Container>
          <Switch>

            <Route exact path="/login">
              <Login />
            </Route>

            <Route exact path="/register">
              <Register />
            </Route>

            <Route exact path="/user/profile">
              <Profile />
            </Route>

            <Route exact path="/pet/mypets">
              <MyPets />
            </Route>

            <Route exact path="/pet/add">
              <AddPet />
            </Route>

            <Route exact path="/pet/edit/:id">
              <EditPet />
            </Route>

            <Route exact path="/pet/myadoptions">
              <MyAdoptions />
            </Route>

            <Route exact path="/castracao">
              <Castracao />
            </Route>

            <Route exact path="/pet/:id">
              <PetDetails />
            </Route>


            <Route exact path="/arvore/myarvore">
              <MyArvore />
            </Route>

            <Route exact path="/arvore/add">
              <AddArvore />
            </Route>

            <Route exact path="/arvore/edit/:id">
              <EditArvore />
            </Route>

            <Route exact path="/arvore/myrequests">
              <MyRequests />
            </Route>

            <Route exact path="/arvores">
              <TreesHome />
            </Route>

            <Route exact path="/arvore/:id">
              <ArvoreDetails />
            </Route>

            <Route exact path="/sobre">
              <About />
            </Route>

            <Route exact path="/denunciar">
              <Denounce />
            </Route>

            <Route exact path="/sama">
              <Sama />
            </Route>

            <Route exact path="/zoologico">
              <Zoologico />
            </Route>





            <Route exact path="/funcionalidade">
              <Functionality />
            </Route>

            <Route exact path="/adotar">
              <AdoptionHome />
            </Route>

            <Route exact path="/admin/users">
              <ManageUsers />
            </Route>

            <Route exact path="/admin/users/create">
              <CreateUserAdmin />
            </Route>

            <Route exact path="/">
              <Home />
            </Route>
          </Switch>
        </Container>
        <Footer />
        <ScrollToTop />
      </UserProvider>
    </Router>
  );
}

export default App;
