import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useState, useEffect, useContext, useCallback } from 'react'
import { Context } from '../../../context/UserContext'

import styles from './MyRequests.module.css'

import RoundedImage from '../../layout/RoundedImage'

function MyRequests() {
    const [arvores, setArvores] = useState([])
    const [token] = useState(localStorage.getItem('token') || '')
    const { user } = useContext(Context)




    const loadRequests = useCallback(() => {
        if (token) {
            api.get('/arvores/myrequests', {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`,
                },
            })
                .then((response) => {
                    setArvores(response.data.arvores || [])
                })
                .catch(() => {
                    setArvores([])
                })
        }
    }, [token])

    useEffect(() => {
        loadRequests()

        // Recarregar a cada 5 segundos para verificar atualizações
        const interval = setInterval(() => {
            loadRequests()
        }, 5000)

        // Recarregar quando a janela ganha foco
        const handleFocus = () => {
            loadRequests()
        }
        window.addEventListener('focus', handleFocus)

        return () => {
            clearInterval(interval)
            window.removeEventListener('focus', handleFocus)
        }
    }, [loadRequests])


    return (
        <section>
            <div className={styles.petlist_header}>
                <h1>Minhas Solicitações</h1>
            </div>
            <div className={styles.petlist_container}>
                {arvores.length > 0 &&
                    arvores.map((arvore) => {
                        const isAdopter = arvore.adopter && (arvore.adopter._id === user._id || arvore.adopter._id === user._id?.toString())
                        const isRequester = arvore.requester && (arvore.requester._id === user._id || arvore.requester._id === user._id?.toString())

                        // Define status styles
                        const statusStyle = {
                            color: '#fff',
                            fontWeight: '600',
                            fontSize: '0.9em',
                            padding: '0.5em 1em',
                            background: '#749666',
                            borderRadius: '8px',
                            margin: 0,
                        }

                        return (
                            <div className={styles.petlist_row} key={arvore._id}>
                                {arvore.images && arvore.images.length > 0 && arvore.images[0] ? (
                                    <RoundedImage
                                        src={`${getApiBase()}/images/arvores/${arvore.images[0]}`}
                                        alt={arvore.species}
                                        width="px75"
                                    />
                                ) : null}
                                <span className={styles.species_name}>{arvore.species}</span>
                                <div className={styles.donor_info}>
                                    <h4 className={styles.donor_title}>
                                        <span className={styles.icon}>👤</span>
                                        Informações da Sama
                                    </h4>
                                    <div className={styles.donor_details}>
                                        <div className={styles.info_item}>
                                            <span className={styles.info_label}>Nome:</span>
                                            <span className={styles.info_value}>Administrador SAMA</span>
                                        </div>
                                        <div className={styles.info_item}>
                                            <span className={styles.info_label}>Telefone:</span>
                                            <span className={styles.info_value}>(14) 3471-3499</span>
                                        </div>
                                        <div className={styles.info_item}>
                                            <span className={styles.info_label}>Localização:</span>
                                            <span className={styles.info_value}>Sama Garça</span>
                                        </div>
                                    </div>
                                </div>
                                <div className={styles.actions}>
                                    {isAdopter ? (
                                        <p style={statusStyle}>
                                            🎉 Concluído com Sucesso!
                                        </p>
                                    ) : isRequester ? (
                                        <div className={styles.status_container}>
                                            <div className={styles.status_info}>
                                                <p className={styles.status_badge} style={{
                                                    ...statusStyle,
                                                    background: arvore.requester.status === 'Aprovado' ? '#749666' :
                                                        arvore.requester.status === 'Recusado' ? '#f44336' :
                                                            arvore.requester.status === 'Em análise' ? '#ff9800' : '#749666'
                                                }}>
                                                    {arvore.requester.status || 'Pendente'}
                                                </p>
                                            </div>

                                            {arvore.requester.adminMessage && (
                                                <div className={styles.admin_message_box}>
                                                    <div className={styles.message_header}>
                                                        <span className={styles.icon}>✉️</span>
                                                        <strong>Mensagem da Sama:</strong>
                                                    </div>
                                                    <p className={styles.message_text}>{arvore.requester.adminMessage}</p>
                                                </div>
                                            )}

                                            {arvore.requester.deliveryAddress && (
                                                <div className={styles.delivery_address}>
                                                    <span className={styles.info_label}>
                                                        <span className={styles.icon}>📍</span> Endereço:
                                                    </span>
                                                    <p className={styles.address_text}>{arvore.requester.deliveryAddress}</p>
                                                </div>
                                            )}
                                        </div>
                                    ) : (
                                        <p style={statusStyle}>
                                            🎉 Concluído com Sucesso!
                                        </p>
                                    )}
                                </div>
                            </div>
                        )
                    })}
                {arvores.length === 0 && <p>Ainda não há solicitações de árvores.</p>}
            </div>
        </section>
    )
}

export default MyRequests

