import { getApiBase } from '../../utils/api'
import { useState, useEffect } from 'react'

import formStyles from './Form.module.css'
import Input from './Input'

function ArvoreForm({ handleSubmit, arvoreData, btnText }) {
  const [arvore, setArvore] = useState(arvoreData || {})
  const [preview, setPreview] = useState([])

  // Atualizar o estado quando arvoreData mudar (apenas na primeira vez ou quando o ID mudar)
  useEffect(() => {
    if (arvoreData && Object.keys(arvoreData).length > 0) {
      // Só atualiza se for a primeira vez (arvore está vazio) ou se o ID mudou
      if (!arvore._id || (arvoreData._id && arvoreData._id !== arvore._id)) {
        setArvore(arvoreData)
        setPreview([]) // Limpar preview quando receber novos dados
      }
    }
  }, [arvoreData, arvore?._id])

  function onFileChange(e) {
    setPreview(Array.from(e.target.files))
    setArvore({ ...arvore, images: [...e.target.files] })
  }

  function handleChange(e) {
    setArvore({ ...arvore, [e.target.name]: e.target.value })
  }

  function submit(e) {
    e.preventDefault()
    if (handleSubmit) {
      handleSubmit(arvore)
    }
  }

  return (
    <form onSubmit={submit} className={formStyles.form_container} style={{ borderLeft: '4px solid #749666' }}>
      <div className={formStyles.preview_pet_images}>
        {preview.length > 0
          ? preview.map((image, index) =>
            <img
              src={URL.createObjectURL(image)}
              alt={arvore.species || 'Árvore'}
              key={`preview-${index}`} />
          )
          : arvore.images && Array.isArray(arvore.images) && arvore.images.length > 0 && typeof arvore.images[0] === 'string' &&
          arvore.images.map((image, index) => (
            <img
              src={`${getApiBase()}/images/arvores/${image}`}
              alt={arvore.species || 'Árvore'}
              key={`existing-${index}`} />
          ))}
      </div>

      <Input
        text="Imagens da Árvore"
        type="file"
        name="images"
        handleOnChange={onFileChange}
        multiple={true}
      />

      <Input
        text="Espécie"
        type="text"
        name="species"
        placeholder="Digite a espécie da árvore"
        handleOnChange={handleChange}
        value={arvore.species || ''}
      />

      <Input
        text="Nome Científico"
        type="text"
        name="scientificName"
        placeholder="Digite o nome científico da árvore"
        handleOnChange={handleChange}
        value={arvore.scientificName || ''}
      />

      <Input
        text="Origem"
        type="text"
        name="origin"
        placeholder="Ex: Nativa, Exótica, etc..."
        handleOnChange={handleChange}
        value={arvore.origin || ''}
      />


      <Input
        text="Idade da Árvore"
        type="text"
        name="age"
        placeholder="Digite a idade da árvore"
        handleOnChange={handleChange}
        value={arvore.age || ''}
      />

      <Input
        text="Porte (Altura)"
        type="text"
        name="height"
        placeholder="Ex: Pequeno, Médio, 2 metros..."
        handleOnChange={handleChange}
        value={arvore.height || ''}
      />

      <Input
        text="Localização"
        type="text"
        name="location"
        placeholder="Digite a localização"
        handleOnChange={handleChange}
        value={arvore.location || ''}
      />
      <div className={formStyles.form_control}>
        <label htmlFor="allowsWiring">Aceita Fiação?</label>
        <select
          name="allowsWiring"
          id="allowsWiring"
          onChange={handleChange}
          value={arvore.allowsWiring !== undefined ? String(arvore.allowsWiring) : ''}
        >
          <option value="">Selecione uma opção</option>
          <option value="true">Sim (Pode ter fiação)</option>
          <option value="false">Não (Não pode ter fiação)</option>
        </select>
      </div>
      <Input
        text="Informe a descrição da árvore"
        type="text"
        name="description"
        placeholder="Digite a descrição da árvore"
        handleOnChange={handleChange}
        value={arvore.description || ''}
      />

      <Input
        text="Quantidade"
        type="number"
        name="quantity"
        placeholder="Digite a quantidade disponível"
        handleOnChange={handleChange}
        value={arvore.quantity || ''}
      />

      <input type="submit" value={btnText} />
    </form>
  )
}

export default ArvoreForm

