import { useState, useEffect } from 'react'
import bus from '../../utils/bus'
import styles from './Message.module.css'

function Message() {
    const [visibility, setVisibility] = useState(false)
    const [message, setMessage] = useState('')
    const [type, setType] = useState('')

    useEffect(() => {
        function handleFlash({ message, type }) {
            setVisibility(true)
            setMessage(message)
            setType(type)

            // Mensagens de sucesso ficam visíveis por mais tempo (5 segundos)
            // Mensagens de erro ficam por 3 segundos
            const displayTime = type === 'success' ? 5000 : 3000

            setTimeout(() => {
                setVisibility(false)
            }, displayTime)
        }

        bus.addListener('flash', handleFlash)

        return () => {
            bus.removeListener('flash', handleFlash)
        }
    }, [])

    return (
        visibility && (
            <div className={`${styles.message} ${styles[type]}`}>
                {message}
            </div>
        )
    )
}

export default Message
