import api from '../../utils/api'
import { getApiBase } from '../../utils/api'
import { useState } from 'react'
import { FaTimes, FaChevronLeft, FaChevronRight, FaExclamationTriangle } from 'react-icons/fa'
import { Link } from 'react-router-dom'
import useFlashMessage from '../../hooks/useFlashMessage'
import styles from './ArvoreModal.module.css'


function ArvoreModal({ arvore, onClose }) {
    const [currentImageIndex, setCurrentImageIndex] = useState(0)
    const [token] = useState(localStorage.getItem('token') || '')
    const [showAddressForm, setShowAddressForm] = useState(false)
    const [address, setAddress] = useState('')
    const { setFlashMessage } = useFlashMessage()

    if (!arvore) return null

    const images = arvore.images || []

    const nextImage = () => {
        if (images.length > 0) {
            setCurrentImageIndex((prev) => (prev + 1) % images.length)
        }
    }

    const prevImage = () => {
        if (images.length > 0) {
            setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length)
        }
    }

    async function requestMuda() {
        if (!address.trim()) {
            setFlashMessage('Por favor, informe o endereço de entrega/plantio', 'error')
            return
        }


        try {
            const response = await api.patch(`/arvores/request/${arvore._id}`, {
                deliveryAddress: address.trim()
            }, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })

            setFlashMessage(response.data.message || 'Solicitação enviada com sucesso!', 'success')
            setShowAddressForm(false)
            setAddress('')
            setTimeout(() => {
                onClose()
                window.location.reload()
            }, 2000)

        } catch (err) {
            setFlashMessage(err.response?.data?.message || 'Erro ao solicitar muda.', 'error')
        }
    }

    return (
        <div className={styles.overlay} onClick={onClose}>
            <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
                <button className={styles.close_button} onClick={onClose}>
                    <FaTimes />
                </button>

                <div className={styles.content}>
                    <div className={styles.carousel_section}>
                        {images.length > 0 ? (
                            <div className={styles.image_container}>
                                <div
                                    className={styles.main_image}
                                    style={{
                                        backgroundImage: `url(${getApiBase()}/images/arvores/${images[currentImageIndex]})`
                                    }}
                                />
                                {images.length > 1 && (
                                    <>
                                        <button className={styles.nav_btn} onClick={prevImage}><FaChevronLeft /></button>
                                        <button className={`${styles.nav_btn} ${styles.nav_right}`} onClick={nextImage}><FaChevronRight /></button>
                                        <div className={styles.dots}>
                                            {images.map((_, idx) => (
                                                <span
                                                    key={idx}
                                                    className={`${styles.dot} ${idx === currentImageIndex ? styles.active_dot : ''}`}
                                                    onClick={() => setCurrentImageIndex(idx)}
                                                />
                                            ))}
                                        </div>
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className={styles.no_image}>
                                <p>Sem imagem</p>
                            </div>
                        )}
                    </div>

                    <div className={styles.info_section}>
                        <h2 className={styles.arvore_name}>{arvore.species}</h2>

                        <div className={styles.details_grid}>
                            {arvore.scientificName && <p><strong>Nome Científico:</strong> {arvore.scientificName}</p>}
                            {arvore.origin && <p><strong>Origem:</strong> {arvore.origin}</p>}
                            {arvore.age && <p><strong>Idade Aproximada:</strong> {arvore.age}</p>}
                            {arvore.height && <p><strong>Porte (Altura):</strong> {arvore.height}</p>}
                            <p>
                                <strong>Indicação para Fiação:</strong> {arvore.allowsWiring ?
                                    <span style={{ color: '#749666', fontWeight: 'bold' }}>Sim (Aceita fiação) ✅</span> :
                                    <span style={{ color: '#e74c3c', fontWeight: 'bold' }}>Não (Não aceita fiação) ⚠️</span>
                                }
                            </p>
                            {arvore.location && <p><strong>Localização:</strong> {arvore.location}</p>}
                            {arvore.quantity && <p><strong>Quantidade disponível:</strong> {arvore.quantity}</p>}
                            {arvore.user && (
                                <>
                                    <p><strong>Responsável:</strong> Administrador SAMA</p>
                                    {arvore.user.phone && <p><strong>Telefone:</strong> {arvore.user.phone}</p>}
                                </>
                            )}
                        </div>

                        {arvore.description && (
                            <div className={styles.description}>
                                <h3>Sobre a Muda:</h3>
                                <p>{arvore.description}</p>
                            </div>
                        )}

                        <div className={styles.actions}>
                            {token ? (
                                arvore.available ? (
                                    !showAddressForm ? (
                                        <button onClick={() => setShowAddressForm(true)} className={styles.request_btn}>
                                            Solicitar Muda
                                        </button>
                                    ) : (
                                        <div className={styles.address_form_container}>
                                            <div className={styles.form_header}>
                                                <label className={styles.form_label}>
                                                    Endereço de Entrega/Plantio
                                                </label>
                                                <p className={styles.form_subtitle}>SAMA entrará em contato para agendar:</p>
                                            </div>
                                            <textarea
                                                value={address}
                                                onChange={(e) => setAddress(e.target.value)}
                                                placeholder="Ex: Rua, Número, Bairro, Cidade..."
                                                className={styles.address_textarea}
                                            />
                                            <div className={styles.form_buttons}>
                                                <button
                                                    onClick={requestMuda}
                                                    className={styles.submit_button}
                                                >
                                                    Enviar Solicitação
                                                </button>
                                                <button
                                                    onClick={() => {
                                                        setShowAddressForm(false)
                                                        setAddress('')
                                                    }}
                                                    className={styles.cancel_button}
                                                >
                                                    Cancelar
                                                </button>
                                            </div>
                                        </div>
                                    )
                                ) : (
                                    <div className={styles.status_message}>
                                        <FaExclamationTriangle className={styles.status_icon} />
                                        <span>Muda indisponível no momento.</span>
                                    </div>
                                )
                            ) : (
                                <div className={styles.login_prompt}>
                                    <p>
                                        Você precisa <Link to="/login" className={styles.link_bold}>entrar</Link> ou <Link to="/register" className={styles.link_bold}>criar conta</Link> para solicitar.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default ArvoreModal
