import styles from './AddArvore.module.css'

/* components */
import ArvoreForm from '../../form/ArvoreForm'
import { useState } from 'react'
import useFlashMessage from '../../../hooks/useFlashMessage'
import { useHistory } from 'react-router-dom'
import api from '../../../utils/api'

function AddArvore() {
    const [token] = useState(localStorage.getItem('token') || '')
    const {setFlashMessage} = useFlashMessage()
    const history = useHistory()

    async function register(arvore) {
        let msgType = 'success'

        const formData = new FormData()
        
        Object.keys(arvore).forEach((key) => {
            if(key === 'images' && arvore[key] && arvore[key].length > 0) {
                for(let i = 0; i < arvore[key].length; i++) {
                    formData.append('images', arvore[key][i])
                }
            } else if(key !== 'images' && arvore[key] !== null && arvore[key] !== undefined && arvore[key] !== '') {
                formData.append(key, arvore[key])
            }
        })

        const data = await api.post('arvores/create', formData, {
            headers: {
                Authorization: `Bearer ${JSON.parse(token)}`,
                'Content-Type': 'multipart/form-data'
            }
        })
        .then((response) => {
            return response.data
        })
        .catch((err) => {
            msgType = 'error'
            return err.response?.data || { message: 'Erro ao cadastrar árvore' }
        })

        setFlashMessage(data.message, msgType)
        if(msgType !== 'error')
            history.push('/arvore/myarvore')
    }
    return (
        <section className={styles.addarvore_header}>
            <div>
            <h1>Cadastre uma Árvore</h1>
            <p>Depois ela ficará disponivel para adoção</p>
            </div>
            <p>Formulário</p>
            <ArvoreForm handleSubmit={register} btnText="Cadastrar Árvore" />
        </section>
    )
}

export default AddArvore

