import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useState, useEffect } from 'react'

import styles from './Profile.module.css'
import formStyles from '../../form/Form.module.css'

import Input from '../../form/Input'

import useFlashMessage from '../../../hooks/useFlashMessage'
import RoundedImage from '../../layout/RoundedImage'

function Profile() {

    const [user, setUser] = useState({})
    const [preview, setPreview] = useState()
    const [token] = useState(localStorage.getItem('token') || '')
    const { setFlashMessage } = useFlashMessage()

    useEffect(() => {
        api.get('/users/checkuser', {
            headers: {
                Authorization: `Bearer ${JSON.parse(token)}`,
            }
        }).then((response) => {
            setUser(response.data)
        })
    }, [token])

    function onFileChange(e) {
        setPreview(e.target.files[0])
        setUser({ ...user, [e.target.name]: e.target.files[0] })
    }

    function maskCPF(value) {
        if (!value) return ''
        return value
            .replace(/\D/g, '')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d{1,2})/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskCNPJ(value) {
        if (!value) return ''
        return value
            .replace(/\D/g, '')
            .replace(/(\d{2})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1/$2')
            .replace(/(\d{4})(\d)/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1')
    }

    function maskPhone(value) {
        if (!value) return ''
        return value
            .replace(/\D/g, '')
            .replace(/(\d{2})(\d)/, '($1) $2')
            .replace(/(\d{5})(\d)/, '$1-$2')
            .replace(/(-\d{4})\d+?$/, '$1')
    }

    function handleChange(e) {
        let value = e.target.value
        const name = e.target.name

        if (name === 'cpf_cnpj') {
            value = user.userType === 'Instituto' ? maskCNPJ(value) : maskCPF(value)
        } else if (name === 'phone') {
            value = maskPhone(value)
        }

        setUser({ ...user, [name]: value })
    }

    async function handleSubmit(e) {
        e.preventDefault()

        let msgType = 'success'

        const formData = new FormData()

        Object.keys(user).forEach((key) => {
            formData.append(key, user[key])
        })

        const data = await api.patch(
            `/users/edit/${user._id}`,
            formData,
            {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`,
                    'Content-Type': 'multipart/form-data',
                },
            }
        )
            .then((response) => {
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao atualizar perfil' }
            })

        setFlashMessage(data.message, msgType)

        if (msgType === 'success') {
            // usar dados retornados ou recarregar
            if (data.user) {
                setUser(data.user)
            } else {
                // recarregar dados do usuário após atualização
                api.get('/users/checkuser', {
                    headers: {
                        Authorization: `Bearer ${JSON.parse(token)}`,
                    }
                }).then((response) => {
                    setUser(response.data)
                })
            }
            setPreview(null)
        }
    }

    return (
        <section style={{ maxWidth: '900px', margin: '0 auto', padding: '2em 1em' }}>
            <div className={styles.profile_header}>
                <h1 className={styles.profile_title}>Meu Perfil</h1>
                <p className={styles.profile_subtitle}>Gerencie suas informações pessoais</p>
            </div>

            <div className={styles.profile_container}>
                {(user.image || preview) ? (
                    <RoundedImage
                        className={styles.preview_image}
                        src={
                            preview
                                ? URL.createObjectURL(preview)
                                : `${getApiBase()}/images/users/${user.image}`
                        }
                        alt={user.name}
                    />
                ) : (
                    <div style={{
                        width: '150px',
                        height: '150px',
                        borderRadius: '50%',
                        background: '#f5f5f5',
                        margin: '0 auto',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#666',
                        fontSize: '3rem',
                        fontWeight: 'normal',
                        border: '2px solid #ddd'
                    }}>
                        {user.name ? user.name.charAt(0).toUpperCase() : 'U'}
                    </div>
                )}
            </div>

            <form onSubmit={handleSubmit} className={formStyles.form_container}>

                <Input
                    text="Imagem"
                    type="file"
                    name="image"
                    handleOnChange={onFileChange}
                />

                <Input
                    text="E-mail"
                    type="email"
                    name="email"
                    placeholder="Digite o seu e-mail"
                    handleOnChange={handleChange}
                    value={user.email || ''}
                />

                <div className={formStyles.form_control} style={{ marginBottom: '1em' }}>
                    <label style={{ display: 'block', marginBottom: '0.5em', fontWeight: 'bold' }}>Tipo de Usuário:</label>
                    <select
                        name="userType"
                        onChange={handleChange}
                        value={user.userType || 'Pessoa Física'}
                        className={formStyles.select_input}
                    >
                        <option value="Pessoa Física">Pessoa Física</option>
                        <option value="Instituto">Instituto / ONG</option>
                    </select>
                </div>

                {user.userType === 'Instituto' && (
                    <Input
                        text="Nome do Instituto"
                        type="text"
                        name="instituteName"
                        placeholder="Digite o nome da ONG ou Instituto"
                        handleOnChange={handleChange}
                        value={user.instituteName || ''}
                    />
                )}

                <Input
                    text={user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}
                    type="text"
                    name="cpf_cnpj"
                    placeholder={`Digite o seu ${user.userType === 'Instituto' ? 'CNPJ' : 'CPF'}`}
                    handleOnChange={handleChange}
                    value={user.cpf_cnpj || ''}
                />

                <Input
                    text="Nome"
                    type="text"
                    name="name"
                    placeholder="Digite o seu nome"
                    handleOnChange={handleChange}
                    value={user.name || ''}
                />

                <Input
                    text="Telefone"
                    type="text"
                    name="phone"
                    placeholder="Digite o seu telefone"
                    handleOnChange={handleChange}
                    value={user.phone || ''}
                />

                <Input
                    text="Senha"
                    type="password"
                    name="password"
                    placeholder="Digite a sua senha"
                    handleOnChange={handleChange}
                />

                <Input
                    text="Confirmação de senha"
                    type="password"
                    name="confirmpassword"
                    placeholder="Digite a sua senha"
                    handleOnChange={handleChange}
                />

                <input
                    type="submit"
                    value="Salvar Alterações"
                />
            </form>
        </section>
    )
}

export default Profile
