import { getApiBase } from '../../utils/api'
import { useState, useEffect } from 'react'

import formStyles from './Form.module.css'
import Input from './Input'
import Select from './Select'

function PetForm({ handleSubmit, petData, btnText }) {
  const [pet, setPet] = useState(petData || {})
  const [preview, setPreview] = useState([])
  const colors = ["Branco", "Preto", "Cinza", "Caramelo", "Mesclado", "Amarelo", "Chocolate", "Creme"]
  const genders = ["Macho", "Fêmea"]
  const sizes = ["Pequeno", "Médio", "Grande"]
  const [ageValue, setAgeValue] = useState('')
  const [ageUnit, setAgeUnit] = useState('Meses')

  // Atualizar o estado quando petData mudar (apenas na primeira vez ou quando o ID mudar)
  useEffect(() => {
    if (petData && Object.keys(petData).length > 0) {
      if (!pet._id || (petData._id && petData._id !== pet._id)) {
        setPet(petData);
        setPreview([]);
        if (petData.age) {
          const splitAge = petData.age.split(' ')
          if (splitAge.length >= 2) {
            setAgeValue(splitAge[0])
            setAgeUnit(splitAge[1])
          } else {
            setAgeValue(petData.age)
          }
        }
      }
    }
  }, [petData, pet._id]);


  function onFileChange(e) {

    setPreview(Array.from(e.target.files))
    setPet({ ...pet, images: [...e.target.files] })
  }

  function handleChange(e) {
    setPet({ ...pet, [e.target.name]: e.target.value })
  }

  function submit(e) {
    e.preventDefault()
    handleSubmit(pet)
  }


  function handleColor(e) {
    setPet({ ...pet, color: e.target.value })
  }

  function handleGender(e) {
    setPet({ ...pet, gender: e.target.value })
  }

  function handleAgeValue(e) {
    const val = e.target.value
    setAgeValue(val)
    setPet({ ...pet, age: `${val} ${ageUnit}` })
  }

  function handleAgeUnit(e) {
    const unit = e.target.value
    setAgeUnit(unit)
    setPet({ ...pet, age: `${ageValue} ${unit}` })
  }
  return (
    <form onSubmit={submit} className={formStyles.form_container} style={{ borderLeft: '4px solid #749666' }}>
      <div className={formStyles.preview_pet_images}>
        {preview.length > 0
          ? preview.map((image, index) =>
            <img
              src={URL.createObjectURL(image)}
              alt={pet.name || 'Pet'}
              key={`preview-${index}`} />
          )
          : pet.images && Array.isArray(pet.images) && pet.images.length > 0 && typeof pet.images[0] === 'string' &&
          pet.images.map((image, index) => (
            <img
              src={`${getApiBase()}/images/pets/${image}`}
              alt={pet.name || 'Pet'}
              key={`existing-${index}`} />
          ))}
      </div>

      <Input
        text="Imagens do Pet"
        type="file"
        name="images"
        handleOnChange={onFileChange}
        multiple={true}
      />

      <Input
        text="Nome do Pet"
        type="text"
        name="name"
        placeholder="Digite o nome"
        handleOnChange={handleChange}
        value={pet.name || ''}
      />

      <div style={{ display: 'flex', gap: '1rem', alignItems: 'flex-start' }}>
        <div style={{ flex: 1 }}>
          <Input
            text="Idade do Pet"
            type="number"
            name="ageValue"
            placeholder="Ex: 2"
            handleOnChange={handleAgeValue}
            value={ageValue || ''}
          />
        </div>
        <div style={{ flex: 1, marginTop: '-2px' }}>
          <Select
            name="ageUnit"
            text="Unidade"
            options={["Meses", "Anos"]}
            handleOnChange={handleAgeUnit}
            value={ageUnit || 'Meses'}
          />
        </div>
      </div>

      <Input
        text="Peso do Pet"
        type="number"
        name="weight"
        placeholder="Digite o peso"
        handleOnChange={handleChange}
        value={pet.weight !== undefined && pet.weight !== null ? pet.weight : ''}
      />
      <Select
        name="color"
        text="Selecione a cor"
        options={colors}
        handleOnChange={handleColor}
        value={pet.color || ''}
      />

      <Select
        name="size"
        text="Selecione o porte"
        options={sizes}
        handleOnChange={(e) => setPet({ ...pet, size: e.target.value })}
        value={pet.size || ''}
      />

      <Select
        name="gender"
        text="Selecione o gênero"
        options={genders}
        handleOnChange={handleGender}
        value={pet.gender || ''}
      />

      <Select
        name="type"
        text="Selecione a Espécie (Cachorro, Gato ou Outros)"
        options={["Cachorro", "Gato", "Outros"]}
        handleOnChange={(e) => setPet({ ...pet, type: e.target.value })}
        value={pet.type || ''}
      />

      <Input
        text="Raça do Pet"
        type="text"
        name="breed"
        placeholder="Digite a raça (ex: Golden Retriever, Poodle, etc)"
        handleOnChange={handleChange}
        value={pet.breed || ''}
      />

      <input type="submit" value={btnText} />
    </form>
  )
}

export default PetForm
