import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useEffect, useState, useCallback } from 'react'
import { Link } from 'react-router-dom'

import RoundedImage from '../../layout/RoundedImage'

import useFlashMessage from '../../../hooks/useFlashMessage'
import { Context } from '../../../context/UserContext'
import { useContext } from 'react'
import styles from './MyArvore.module.css'
import { generateTreePDF } from '../../../utils/generateTreePDF'
import seloSama from '../../../assets/img/seloSama.png'
import { FaFilePdf } from 'react-icons/fa'

function MyArvore() {

  const [arvores, setArvores] = useState([])
  const [token] = useState(localStorage.getItem('token') || '')
  const { setFlashMessage } = useFlashMessage()
  const [adminMessages, setAdminMessages] = useState({})
  const { user } = useContext(Context)
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false)



  const fetchArvores = useCallback(() => {
    if (token) {
      // Buscar árvores cadastradas e adotadas pelo usuário (o backend já retorna ambas)
      api.get('/arvores/mytrees', {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`
        }
      })
        .then((response) => {
          const arvoresList = response.data.arvores || []
          // Ordenar: árvores com solicitações primeiro (mais recentes primeiro), depois as sem solicitações
          const sortedArvores = arvoresList.sort((a, b) => {
            const aHasRequest = a.requester && a.requester._id
            const bHasRequest = b.requester && b.requester._id

            if (aHasRequest && bHasRequest) {
              const aDate = a.requester.createdAt || a.requester.updatedAt || a.updatedAt || a.createdAt || new Date(0)
              const bDate = b.requester.createdAt || b.requester.updatedAt || b.updatedAt || b.createdAt || new Date(0)
              return new Date(bDate) - new Date(aDate)
            }

            if (aHasRequest && !bHasRequest) return -1
            if (!aHasRequest && bHasRequest) return 1

            return 0
          })
          setArvores(sortedArvores)
        })
        .catch((err) => {
          console.error('Erro ao carregar árvores:', err)
          // setFlashMessage(err.response?.data?.message || 'Erro ao carregar árvores', 'error')
        })
    }
  }, [token])

  useEffect(() => {
    fetchArvores()

    // Recarregar a cada 5 segundos para verificar atualizações (importante para o solicitante ver quando foi aceito)
    const interval = setInterval(() => {
      fetchArvores()
    }, 5000)

    // Recarregar quando a janela ganha foco
    const handleFocus = () => {
      fetchArvores()
    }
    window.addEventListener('focus', handleFocus)

    return () => {
      clearInterval(interval)
      window.removeEventListener('focus', handleFocus)
    }
  }, [token, fetchArvores])


  async function removeArvore(id) {
    let msgType = 'success'

    const data = await api
      .delete(`/arvores/${id}`, {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`,
        },
      })
      .then((response) => {
        const updatedArvores = arvores.filter((arvore) => arvore._id !== id)
        setArvores(updatedArvores)
        return response.data
      })
      .catch((err) => {
        msgType = 'error'
        return err.response.data
      })

    setFlashMessage(data.message, msgType)
  }

  async function updateStatus(id, newStatus) {
    let msgType = 'success'

    // Mapeia os status para as rotas que existem no backend
    let endpoint = ''
    let body = {}
    if (newStatus === 'Aprovado') {
      endpoint = `/arvores/conclude/${id}`
      body = { adminMessage: adminMessages[id] || '' }
    } else if (newStatus === 'Recusado' || newStatus === 'Cancelado') {
      endpoint = `/arvores/cancel/${id}`
      body = { adminMessage: adminMessages[id] || '' }
    } else {
      // Para status como 'Em análise' ou 'Pendente', usa a rota de status
      endpoint = `/arvores/status/${id}`
      body = { status: newStatus, adminMessage: adminMessages[id] || '' }
    }

    const data = await api.patch(endpoint, body, {
      headers: {
        Authorization: `Bearer ${JSON.parse(token)}`,
      },
    }).then((response) => {
      setAdminMessages(prev => ({ ...prev, [id]: '' })) // Limpar mensagem após sucesso
      return response.data
    }).catch((err) => {
      msgType = 'error'
      return err.response?.data || { message: 'Erro ao atualizar status' }
    })

    setFlashMessage(data.message, msgType)

    if (msgType !== 'error') {
      fetchArvores()
    }
  }

  async function concludeRequest(id) {
    let msgType = 'success'

    const data = await api.patch(`/arvores/conclude/${id}`, {
      headers: {
        Authorization: `Bearer ${JSON.parse(token)}`,
      },
    }).then((response) => {
      return response.data
    }).catch((err) => {
      msgType = 'error'
      return err.response?.data || { message: 'Erro ao concluir solicitação' }
    })

    setFlashMessage(data.message, msgType)
    // Recarregar árvores após concluir
    if (msgType !== 'error') {
      // Atualiza o estado local imediatamente para sumir o botão
      setArvores((prev) =>
        prev.map((arv) =>
          arv._id === id
            ? { ...arv, available: false }
            : arv
        )
      )
      api.get('/arvores/mytrees', {
        headers: {
          Authorization: `Bearer ${JSON.parse(token)}`
        }
      })
        .then((response) => {
          const arvoresList = response.data.arvores || []
          // Ordenar: árvores com solicitações primeiro (mais recentes primeiro), depois as sem solicitações
          const sortedArvores = arvoresList.sort((a, b) => {
            const aHasRequest = a.requester && a.requester._id
            const bHasRequest = b.requester && b.requester._id

            // Se ambas têm solicitação, ordenar por data mais recente
            if (aHasRequest && bHasRequest) {
              const aDate = a.requester.createdAt || a.requester.updatedAt || a.updatedAt || a.createdAt || new Date(0)
              const bDate = b.requester.createdAt || b.requester.updatedAt || b.updatedAt || b.createdAt || new Date(0)
              return new Date(bDate) - new Date(aDate)
            }

            // Se só uma tem solicitação, ela vem primeiro
            if (aHasRequest && !bHasRequest) return -1
            if (!aHasRequest && bHasRequest) return 1

            // Se nenhuma tem solicitação, manter ordem original
            return 0
          })
          setArvores(sortedArvores)
        })
        .catch(() => { })
    }
  }

  async function cancelRequest(id) {
    let msgType = 'success'

    const data = await api.patch(`/arvores/cancel/${id}`, {}, {
      headers: {
        Authorization: `Bearer ${JSON.parse(token)}`,
      },
    }).then((response) => {
      return response.data
    }).catch((err) => {
      msgType = 'error'
      return err.response?.data || { message: 'Erro ao cancelar solicitação' }
    })

    setFlashMessage(data.message, msgType)
    if (msgType !== 'error') {
      fetchArvores()
    }
  }

  const handleDownloadPDF = async () => {
    setIsGeneratingPDF(true)
    try {
      await generateTreePDF(arvores, seloSama)
    } catch (error) {
      console.error("Erro ao gerar PDF:", error)
      setFlashMessage("Erro ao gerar o PDF. Tente novamente.", "error")
    } finally {
      setIsGeneratingPDF(false)
    }
  }

  return (
    <section className={styles.my_arvore_section}>
      {!(user?.isAdmin || user?.canManageTrees) ? (
        <>
          <div className={styles.petlist_header}>
            <h1>Acesso Restrito</h1>
          </div>
          <p>Você não possui permissão para gerenciar o cadastro de mudas.</p>
        </>
      ) : (
        <>
          <div className={styles.petlist_header}>
            <h1 className={styles.klinic_title}>{(user?.isAdmin || user?.canManageTrees) ? 'Gerenciar Mudas' : 'Minhas Mudas'}</h1>
            {arvores.length > 0 && <p style={{ fontSize: '1.1rem', color: '#000', marginTop: '5px' }}>{arvores.length} espécies cadastradas</p>}
            <div className={styles.header_actions}>
              {(user?.isAdmin || user?.canManageTrees) && (
                <>
                  <button
                    onClick={handleDownloadPDF}
                    className={styles.pdf_btn}
                    disabled={isGeneratingPDF || arvores.length === 0}
                  >
                    <FaFilePdf /> {isGeneratingPDF ? 'Gerando...' : 'Baixar PDF'}
                  </button>
                  <Link to="/arvore/add" className={styles.addBtn}>Cadastrar Árvore/Muda</Link>
                </>
              )}
            </div>
          </div>

          <div className={styles.petlist_container}>
            {arvores.length > 0 &&
              arvores.map((arvore) => {
                const isOwner = user?.isAdmin || user?.canManageTrees || (arvore.user && (arvore.user._id === user?._id || arvore.user._id === user?._id?.toString()))
                const isAuthorizedToSee = user?.isAdmin || user?.canManageTrees || user?.isSamaMember

                return (
                  <div className={styles.petlist_row} key={arvore._id}>
                    {arvore.images && arvore.images.length > 0 && arvore.images[0] ? (
                      <RoundedImage
                        src={`${getApiBase()}/images/arvores/${arvore.images[0]}`}
                        alt={arvore.species}
                        width="px75"
                      />
                    ) : (
                      <div className={styles.no_image_placeholder}>
                        <span>Sem imagem</span>
                      </div>
                    )}

                    <div className={styles.arvore_info_container}>
                      <span className={styles.arvore_name}>{arvore.species}</span>

                      {arvore.requester && isOwner && (
                        <div className={styles.status_wrapper_admin}>
                          <span className={`${styles.status_badge_mini} ${styles['status_' + arvore.requester.status?.toLowerCase().replace(/\s/g, '_')] || ''}`}>
                            Status: {arvore.requester.status}
                          </span>
                        </div>
                      )}

                      {/* SE FOR O DONO OU AUTORIZADO, MOSTRA DETALHES COMPLETOS */}
                      {isOwner || isAuthorizedToSee ? (
                        <>
                          <div className={styles.arvore_details}>
                            <div className={styles.info_row}>
                              <div className={styles.info_item}>
                                <span className={styles.info_label}>Localização</span>
                                <span className={styles.info_value}>{arvore.location}</span>
                              </div>
                            </div>
                            <div className={styles.info_row}>
                              <div className={styles.info_item}>
                                <span className={styles.info_label}>Quantidade</span>
                                <span className={styles.info_value}>{arvore.quantity}</span>
                              </div>
                            </div>
                          </div>
                          {arvore.requester && isOwner && (
                            <div className={styles.requester_info}>
                              <div className={styles.requester_header}>
                                <span className={styles.requester_title}>Pessoa solicitando</span>
                              </div>
                              <div className={styles.requester_details}>
                                <div className={styles.info_row}>
                                  <div className={styles.info_item}>
                                    <span className={styles.info_label}>Nome</span>
                                    <span className={styles.info_value}>{arvore.requester.name}</span>
                                  </div>
                                </div>
                                {arvore.requester.phone && (
                                  <div className={styles.info_row}>
                                    <div className={styles.info_item}>
                                      <span className={styles.info_label}>Telefone</span>
                                      <span className={styles.info_value}>{arvore.requester.phone}</span>
                                    </div>
                                  </div>
                                )}
                                {arvore.requester.email && (
                                  <div className={styles.info_row}>
                                    <div className={styles.info_item}>
                                      <span className={styles.info_label}>E-mail</span>
                                      <span className={styles.info_value}>{arvore.requester.email}</span>
                                    </div>
                                  </div>
                                )}
                                {arvore.requester.deliveryAddress && (
                                  <div className={styles.delivery_address}>
                                    <div className={styles.delivery_header}>
                                      <span className={styles.delivery_icon}>📍</span>
                                      <span className={styles.delivery_label}>Endereço de Entrega</span>
                                    </div>
                                    <p className={styles.address_text}>{arvore.requester.deliveryAddress}</p>
                                  </div>
                                )}
                              </div>
                            </div>
                          )}
                        </>
                      ) : (
                        /* SE NÃO FOR O DONO (É O REQUERENTE/ADOTANTE), MOSTRA DADOS DO DONO */
                        <div className={styles.contacts}>
                          <p style={{ marginBottom: '.5em', fontWeight: 'bold', color: '#749666' }}>Status da Solicitação:</p>
                          {arvore.requester && (
                            <div className={styles.status_indicator}>
                              {arvore.requester.status === 'Pendente' && <span className={styles.orange_text}>✅ Solicitação enviada com sucesso!</span>}
                              {arvore.requester.status === 'Em análise' && <span className={styles.orange_text}>⏳ Sua solicitação está em análise.</span>}
                              {arvore.requester.status === 'Aprovado' && <span className={styles.green_text}>🎉 Solicitação aprovada!</span>}
                              {arvore.requester.status === 'Recusado' && <span className={styles.red_text}>❌ Solicitação não aprovada.</span>}

                              {arvore.requester.adminMessage && (
                                <div className={styles.admin_response_box}>
                                  <strong>Informação SAMA:</strong>
                                  <p>{arvore.requester.adminMessage}</p>
                                </div>
                              )}
                            </div>
                          )}
                          {arvore.adopter && (
                            <div className={styles.status_indicator}>
                              <span className={styles.green_text}>🏁 Finalizado</span>
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                    <div className={styles.actions}>
                      {isOwner ? (
                        /* AÇÕES PARA O DONO */
                        <>
                          {arvore.requester && arvore.available && (
                            <div className={styles.admin_controls}>
                              <div className={styles.message_control}>
                                <textarea
                                  placeholder="Escreva alguma informação ou observação adicional (ex: local de retirada, data prevista...)"
                                  value={adminMessages[arvore._id] || ''}
                                  onChange={(e) => setAdminMessages(prev => ({ ...prev, [arvore._id]: e.target.value }))}
                                  className={styles.admin_textarea}
                                />
                              </div>
                              <div className={styles.button_group}>
                                <button
                                  className={`${styles.analysis_btn} ${arvore.requester.status === 'Em análise' ? styles.active_status : ''}`}
                                  onClick={() => updateStatus(arvore._id, 'Em análise')}
                                >
                                  ⏳ Em análise
                                </button>
                                <button
                                  className={`${styles.accept_btn} ${arvore.requester.status === 'Aprovado' ? styles.active_status : ''}`}
                                  onClick={() => updateStatus(arvore._id, 'Aprovado')}
                                >
                                  ✅ Aprovar
                                </button>
                                <button
                                  className={`${styles.reject_btn} ${arvore.requester.status === 'Recusado' ? styles.active_status : ''}`}
                                  onClick={() => updateStatus(arvore._id, 'Recusado')}
                                >
                                  ❌ Recusar
                                </button>
                                <button
                                  className={styles.delete_request_btn}
                                  onClick={() => cancelRequest(arvore._id)}
                                  title="Remover solicitante e limpar status"
                                >
                                  🗑️ Apagar Solicitação
                                </button>
                              </div>

                              {arvore.requester.status === 'Aprovado' && (
                                <button
                                  className={styles.conclude_btn}
                                  onClick={() => concludeRequest(arvore._id)}
                                >
                                  Finalizar
                                </button>
                              )}
                            </div>
                          )}

                          {!arvore.available && (
                            <div className={styles.concluded_badge}>
                              <span className={styles.check_icon}>✓</span>
                              Entrega Concluída
                            </div>
                          )}

                          {isOwner && (
                            <>
                              <Link to={`/arvore/edit/${arvore._id}`} className={styles.edit_btn}>
                                Editar
                              </Link>
                              <button
                                className={styles.delete_btn}
                                onClick={() => removeArvore(arvore._id)}
                              >
                                Excluir
                              </button>
                            </>
                          )}
                        </>
                      ) : (
                        /* AÇÕES PARA O REQUERENTE/ADOTANTE */
                        <>
                          {arvore.requester && arvore.requester._id === user?._id && (
                            <>
                              {arvore.available ? (
                                <div className={`${styles.status_badge} ${styles[arvore.requester?.status?.replace(/\s/g, '_')]}`}>
                                  {arvore.requester?.status}
                                </div>
                              ) : (
                                <div className={styles.concluded_badge}>
                                  Finalizado
                                </div>
                              )}
                            </>
                          )}
                        </>
                      )}
                    </div>
                  </div>
                )
              })}

            {arvores.length === 0 && <p>Não há árvores cadastradas</p>}
          </div>
        </>
      )}
    </section>
  )
}

export default MyArvore
