import styles from './About.module.css'
import petcapa1 from '../../../assets/img/petcapa1.png'
import sobreImg from '../../../assets/img/sobre.png'
import { FaPaw, FaSearch, FaSeedling, FaClipboardList, FaHeartbeat, FaLeaf, FaHandHoldingHeart, FaInfoCircle } from 'react-icons/fa'
import { Link } from 'react-router-dom'

function About() {
    return (
        <section className={styles.about_container}>
            {/* Background Decor */}
            <div className={styles.paw_background_container}>
                <FaPaw className={`${styles.paw_decor} ${styles.paw_1}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_2}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_3}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_4}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_5}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_6}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_7}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_8}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_9}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_10}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_11}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_12}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_13}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_14}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_15}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_16}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_17}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_18}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_19}`} />
                <FaPaw className={`${styles.paw_decor} ${styles.paw_20}`} />
            </div>

            <div className={styles.content_wrapper}>
                <div className={styles.main_content}>
                    <div className={styles.intro_section}>

                        <h1 className={styles.main_title}>
                            Sobre o <span className={styles.garca}>Garça</span><span className={styles.pet}>Pet</span>
                        </h1>
                        <p className={styles.description}>
                            O <strong>Adote Garça</strong> é uma plataforma digital desenvolvida pela Prefeitura Municipal de Garça,
                            O projeto <strong>Garça Pet</strong> nasceu da união entre tecnologia e compaixão. Nosso objetivo é transformar a realidade da causa animal em nossa cidade, criando pontes entre quem quer ajudar e os animais que mais precisam.
                        </p>
                        <p className={styles.description}>
                            Através de uma plataforma integrada, facilitamos processos que antes eram burocráticos ou desconhecidos pela população, trazendo transparência e eficiência para a gestão da fauna urbana.
                        </p>
                    </div>

                    <div className={styles.propósito_section}>

                        <h2 className={styles.section_title_orange}>Nossos Pilares</h2>
                        <ul className={styles.info_list_bullet}>
                            <li><strong>Consciência:</strong> Educar a população sobre a posse responsável e o respeito aos seres vivos.</li>
                            <li><strong>Inovação:</strong> Utilizar ferramentas digitais para otimizar adoções e solicitações de mudas.</li>
                            <li><strong>Sustentabilidade:</strong> Integrar a causa animal com a preservação ambiental da nossa Garça.</li>
                            <li><strong>Transparência:</strong> Oferecer visibilidade aos programas municipais e processos de cuidado.</li>
                        </ul>
                    </div>

                </div>

                <div className={styles.side_image_container}>
                    <div className={styles.pet_shape_custom}>
                        <img src={petcapa1} alt="Pet Hero" className={styles.shape_img} />
                    </div>
                </div>
            </div>

            {/* Importance Section */}
            <div className={styles.importance_section_full}>
                <div className={styles.importance_paws_container}>
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_1}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_2}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_3}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_4}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_5}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_6}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_7}`} />
                    <FaPaw className={`${styles.importance_paw} ${styles.imp_paw_8}`} />
                </div>
                <div className={styles.importance_container}>
                    <div className={styles.importance_image_wrapper}>
                        <img src={sobreImg} alt="Sobre o Projeto" className={styles.importance_img} />
                    </div>
                    <div className={styles.importance_text}>
                        <h2 className={styles.section_title_orange}>A Importância do Projeto</h2>
                        <p className={styles.description}>
                            A plataforma digital centraliza informações e serviços essenciais, garantindo que cada cidadão tenha as ferramentas necessárias para contribuir com um ambiente urbano mais harmonioso e acolhedor para todos.
                        </p>
                        <p className={styles.description}>
                            Ao conectar a Secretaria de Meio Ambiente diretamente com a população, o Garça Pet acelera o atendimento de denúncias, as solicitações de plantio e, principalmente, a chance de um animal de abrigo encontrar um novo lar.
                        </p>
                    </div>
                </div>
            </div>

            {/* Services Section */}
            <div className={styles.services_full_width}>
                <div className={styles.services_paws_container}>
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_1}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_2}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_3}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_4}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_5}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_6}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_7}`} />
                    <FaPaw className={`${styles.service_paw} ${styles.s_paw_8}`} />
                </div>
                <div className={styles.services_section}>
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_1}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_2}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_3}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_4}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_5}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_6}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_7}`} />
                    <FaPaw className={`${styles.grid_paw} ${styles.g_paw_8}`} />

                    <h2 className={styles.section_title_orange}>O que você pode fazer na plataforma</h2>
                    <div className={styles.features_grid_three}>
                        <Link to="/adotar" className={`${styles.feature_item} ${styles.card_adopt}`}>
                            <div className={styles.card_tag}>01</div>
                            <div className={styles.icon_box}><FaSearch /></div>
                            <div className={styles.card_content}>
                                <h3>Adoção Pet</h3>
                                <p>Encontre o seu novo melhor amigo e dê a ele um lar cheio de amor.</p>
                                <span className={styles.card_cta}>Ver Pets</span>
                            </div>
                            <div className={styles.card_arrow}>→</div>
                            <FaPaw className={styles.card_bg_icon} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_1}`} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_2}`} />
                        </Link>
                        <Link to="/arvores" className={`${styles.feature_item} ${styles.card_tree}`}>
                            <div className={styles.card_tag}>02</div>
                            <div className={styles.icon_box}><FaSeedling /></div>
                            <div className={styles.card_content}>
                                <h3>Árvores</h3>
                                <p>Solicite mudas para transformar sua rua em um lugar mais verde.</p>
                                <span className={styles.card_cta}>Solicitar</span>
                            </div>
                            <div className={styles.card_arrow}>→</div>
                            <FaLeaf className={styles.card_bg_icon} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_1}`} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_2}`} />
                        </Link>
                        <Link to="/castracao" className={`${styles.feature_item} ${styles.card_castration}`}>
                            <div className={styles.card_tag}>03</div>
                            <div className={styles.icon_box}><FaHeartbeat /></div>
                            <div className={styles.card_content}>
                                <h3>Castração</h3>
                                <p>Acesse informações sobre o programa de castração gratuita.</p>
                                <span className={styles.card_cta}>Informações</span>
                            </div>
                            <div className={styles.card_arrow}>→</div>
                            <FaHandHoldingHeart className={styles.card_bg_icon} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_1}`} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_2}`} />
                        </Link>
                        <Link to="/pet/myadoptions" className={`${styles.feature_item} ${styles.card_requests}`}>
                            <div className={styles.card_tag}>04</div>
                            <div className={styles.icon_box}><FaClipboardList /></div>
                            <div className={styles.card_content}>
                                <h3>Solicitações</h3>
                                <p>Acompanhe seus pedidos e solicitações de forma prática.</p>
                                <span className={styles.card_cta}>Acompanhar</span>
                            </div>
                            <div className={styles.card_arrow}>→</div>
                            <FaInfoCircle className={styles.card_bg_icon} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_1}`} />
                            <FaPaw className={`${styles.card_bg_small} ${styles.cb_2}`} />
                        </Link>
                    </div>
                </div>
            </div>

        </section >
    )
}

export default About
