import { useState, useEffect, useContext, useRef } from 'react'
import api from '../../../utils/api'
import { Context } from '../../../context/UserContext'
import styles from './Castracao.module.css'

// Images
import castracaoDivulImg from '../../../assets/img/imgcastracaocdivul.png'
import campanhaImg from '../../../assets/img/campanhacastracao2.png'
import benefitSaude from '../../../assets/img/castracao_saude_icon.png'
import benefitAnalise from '../../../assets/img/tutor_analysis_hero.png'
import benefitCarinho from '../../../assets/img/castracao_peace_icon.png'
import castracaoImg from '../../../assets/img/castracaoimg.png'
import closedCastrationImg from '../../../assets/img/avisocastracao.png'

// Icons
import { FaMapMarkerAlt, FaClock, FaPaw, FaBone, FaLock, FaLockOpen, FaChevronLeft, FaChevronRight } from 'react-icons/fa'

function Castracao() {
    const { user } = useContext(Context)
    const [isCastrationClosed, setIsCastrationClosed] = useState(false)
    const benefitCarouselRef = useRef(null)

    const scrollBenefitLeft = () => {
        if (benefitCarouselRef.current) {
            benefitCarouselRef.current.scrollBy({ left: -300, behavior: 'smooth' })
        }
    }

    const scrollBenefitRight = () => {
        if (benefitCarouselRef.current) {
            benefitCarouselRef.current.scrollBy({ left: 300, behavior: 'smooth' })
        }
    }

    useEffect(() => {
        api.get('/settings/castration_closed').then((response) => {
            if (response.data) {
                setIsCastrationClosed(response.data.value)
            }
        }).catch(err => console.log(err))
    }, [])

    const toggleCastrationStatus = async () => {
        try {
            const newValue = !isCastrationClosed
            await api.patch('/settings/update', {
                key: 'castration_closed',
                value: newValue
            }, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(localStorage.getItem('token'))}`
                }
            })
            setIsCastrationClosed(newValue)
        } catch (error) {
            console.error('Erro ao atualizar status', error)
            alert('Erro ao atualizar status.')
        }
    }



    return (
        <section className={styles.castracao_container}>
            {/* Admin/SAMA Floating Button */}
            {user && (user.isAdmin || user.isSamaMember) && (
                <div className={styles.admin_controls}>
                    <button
                        className={`${styles.admin_corner_btn} ${isCastrationClosed ? styles.btn_closed : styles.btn_open}`}
                        onClick={toggleCastrationStatus}
                    >
                        {isCastrationClosed ? <FaLock /> : <FaLockOpen />}
                    </button>
                    <span className={styles.admin_label}>
                        {isCastrationClosed ? "Reabrir Castração" : "Encerrar Castração"}
                    </span>
                </div>
            )}

            {/* Original Campaign Banner Section */}
            <div className={styles.campaign_banner}>
                <img src={campanhaImg} alt="Campanha Castração" className={styles.banner_img_desktop} />
                <img src={castracaoDivulImg} alt="Campanha Castração Mobile" className={styles.banner_img_mobile} />

                {/* Overlay for Closed State */}
                {isCastrationClosed && (
                    <div className={styles.closed_overlay}>
                        <img src={closedCastrationImg} alt="Castração Encerrada" className={styles.closed_image_overlay} />
                    </div>
                )}
            </div>

            {/* Main Content & Logic */}
            <div className={styles.main_wrapper}>
                <div className={styles.text_content}>

                    {/* NEW: Importância da Castração Text Block */}
                    <div className={styles.intro_text_side}>
                        <h2 className={styles.section_title}><FaPaw className={styles.paw_title_icon} /> A Importância da Castração</h2>
                        <p className={styles.main_intro}>
                            A castração é muito mais do que um procedimento cirúrgico; é um ato fundamental de <strong>saúde pública</strong> e <strong>bem-estar animal</strong>. Ao optar pela castração, você está contribuindo diretamente para o controle populacional, evitando que milhares de animais acabem em situações de abandono e sofrimento nas ruas.
                        </p>
                        <p className={styles.main_intro}>
                            Além do controle reprodutivo, os benefícios para a saúde individual do seu pet são imensos. Em fêmeas, a castração precoce reduz em quase 100% as chances de desenvolver câncer de mama e elimina o risco de infecções uterinas graves, como a piometra. Em machos, previne tumores de testículo e problemas na próstata, além de reduzir comportamentos indesejados como a demarcação de território e a agressividade por dominância.
                        </p>
                        <p className={styles.secondary_text}>
                            A Prefeitura de Garça, através da SAMA e SEMADS, entende que uma cidade que cuida de seus animais é uma cidade mais saudável para todos. Nosso programa visa oferecer acesso a esse procedimento vital para famílias de baixa renda, garantindo que a situation financeira não seja um impedimento para o cuidado responsável com nossos amigos de quatro patas.
                        </p>
                    </div>

                    {/* Moved: Original Importance/Benefits Cards */}
                    <div className={styles.importance_section}>
                        <h2 className={styles.section_title_centered}>Benefícios da Castração Responsável</h2>
                        <div className={styles.benefit_carousel_wrapper}>
                            <button className={`${styles.nav_button} ${styles.left}`} onClick={scrollBenefitLeft} aria-label="Anterior">
                                <FaChevronLeft />
                            </button>

                            <div className={styles.benefit_container_cast} ref={benefitCarouselRef}>
                                {/* Card 1 */}
                                <div className={styles.benefit_card_cast_vertical} style={{ borderColor: '#ed9756' }}>
                                    <div className={styles.card_paws}>
                                        <FaPaw className={styles.card_paw_1} /> <FaPaw className={styles.card_paw_2} />
                                        <FaPaw className={styles.card_paw_3} /> <FaPaw className={styles.card_paw_4} />
                                        <FaPaw className={styles.card_paw_5} /> <FaPaw className={styles.card_paw_6} />
                                        <FaBone className={styles.card_bone_1} />
                                    </div>
                                    <div className={styles.benefit_image_wrapper_vertical}>
                                        <img src={benefitSaude} alt="Prevenção" />
                                    </div>
                                    <div className={styles.benefit_text_vertical}>
                                        <strong>Prevenção e Saúde</strong>
                                        <p>Reduz drasticamente o risco de câncer de mama, útero e tumores de próstata no animal.</p>
                                    </div>
                                </div>

                                {/* Card 2 */}
                                <div className={styles.benefit_card_cast_vertical} style={{ borderColor: '#749666' }}>
                                    <div className={styles.card_paws}>
                                        <FaPaw className={styles.card_paw_7} /> <FaPaw className={styles.card_paw_8} />
                                        <FaPaw className={styles.card_paw_9} /> <FaPaw className={styles.card_paw_10} />
                                        <FaPaw className={styles.card_paw_1} /> <FaPaw className={styles.card_paw_2} />
                                        <FaBone className={styles.card_bone_2} />
                                    </div>
                                    <div className={styles.benefit_image_wrapper_vertical}>
                                        <img src={benefitAnalise} alt="Análise" />
                                    </div>
                                    <div className={styles.benefit_text_vertical}>
                                        <strong>Análise do Perfil</strong>
                                        <p>Garantimos que o processo seja seguro, avaliando o perfil de cada animal para o procedimento.</p>
                                    </div>
                                </div>

                                {/* Card 3 */}
                                <div className={styles.benefit_card_cast_vertical} style={{ borderColor: '#ed9756' }}>
                                    <div className={styles.card_paws}>
                                        <FaPaw className={styles.card_paw_3} /> <FaPaw className={styles.card_paw_5} />
                                        <FaPaw className={styles.card_paw_7} /> <FaPaw className={styles.card_paw_9} />
                                        <FaPaw className={styles.card_paw_2} /> <FaPaw className={styles.card_paw_4} />
                                        <FaBone className={styles.card_bone_3} />
                                    </div>
                                    <div className={styles.benefit_image_wrapper_vertical}>
                                        <img src={benefitCarinho} alt="Comportamento" />
                                    </div>
                                    <div className={styles.benefit_text_vertical}>
                                        <strong>Calma e Equilíbrio</strong>
                                        <p>Diminui a agitação, o hábito de fugir e a demarcação de território dentro de casa.</p>
                                    </div>
                                </div>
                            </div>

                            <button className={`${styles.nav_button} ${styles.right}`} onClick={scrollBenefitRight} aria-label="Próximo">
                                <FaChevronRight />
                            </button>
                        </div>
                    </div>

                    {/* Removed Old Castramovel Text to reduce redundancy as requested info is prioritized */}

                    {/* NEW "Como Participar" Section (Integrated) */}
                    <div className={styles.participation_section_new}>

                        {/* Top Flex Row: Image + Intro Block */}
                        <div className={styles.participation_top_row}>
                            <div className={styles.participation_image_side}>
                                {/* Decorative Paws for the Image Area */}
                                <div className={styles.paws_deco_wrapper}>
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.p1}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.p2}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.p3}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.p4}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.p5}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.p6}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.p7}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.p8}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.p9}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.p10}`} />
                                </div>

                                <div className={styles.participation_shape_moldura}>
                                    <img src={castracaoImg} alt="Ilustração Como Participar" className={styles.participation_floating_img} />
                                </div>
                            </div>

                            <div className={styles.faq_intro_block}>
                                {/* Decorative Paws for the Text Area */}
                                <div className={styles.text_paws_deco}>
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp1}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp2}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp3}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp4}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp5}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp6}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp7}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp8}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp9}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp10}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp11}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp12}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp13}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp14}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp15}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp16}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp17}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp18}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp19}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp20}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp21}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp22}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp23}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_orange} ${styles.tp24}`} />
                                    <FaPaw className={`${styles.deco_paw} ${styles.paw_green} ${styles.tp25}`} />
                                </div>
                                <h3><FaPaw className={`${styles.phrase_icon} ${styles.paw_orange}`} /> O QUE VOCÊ PRECISA SABER SOBRE A CASTRAÇÃO?</h3>
                                <p>
                                    Castrar um animal é uma decisão de amor e responsabilidade. O processo envolve etapas importantes para garantir a segurança e o bem-estar do seu pet.
                                    Antes de iniciar, confira as etapas e requisitos abaixo:
                                </p>
                            </div>
                        </div>

                        {/* Centered "COMO PARTICIPAR?" Title Below */}
                        <div className={styles.participation_title_wrapper}>
                            <h2 className={styles.participation_title_main}>
                                <FaPaw className={`${styles.phrase_icon} ${styles.paw_green}`} /> COMO PARTICIPAR?
                            </h2>
                            <div className={styles.title_underline_decor}></div>
                        </div>


                        {/* Steps List (Text Model, No FAQ) */}
                        <div className={styles.steps_container}>

                            {/* Step 1 */}
                            <div className={styles.step_simple}>
                                <h3>1. Retirada do comprovante de baixa renda</h3>
                                <p>O primeiro passo é comparecer à sede da Semads para apresentar a documentação necessária e retirar o comprovante de baixa renda.</p>
                                <div className={styles.step_info_line}>
                                    <FaMapMarkerAlt />
                                    <div><strong>Endereço:</strong> Rua Vital Soares, 56 – Garça/SP</div>
                                </div>
                                <div className={styles.step_info_line}>
                                    <FaClock />
                                    <div><strong>Horário de atendimento:</strong> de segunda a sexta-feira, das 8h às 16h</div>
                                </div>
                            </div>

                            {/* Step 2 */}
                            <div className={styles.step_simple}>
                                <h3>2. Solicitação de autorização na Sama</h3>
                                <p>Com o comprovante em mãos, o tutor deve se dirigir até a Sama, localizada no Bosque Municipal, para obter a autorização para o procedimento.</p>
                                <div className={styles.step_info_line}>
                                    <FaMapMarkerAlt />
                                    <div><strong>Endereço:</strong> Bosque Municipal – Garça/SP</div>
                                </div>
                                <div className={styles.step_info_line}>
                                    <FaClock />
                                    <div><strong>Horário de atendimento:</strong> de segunda a sexta-feira, das 8h às 16h</div>
                                </div>
                            </div>

                            {/* Step 3 */}
                            <div className={styles.step_simple}>
                                <h3>3. Agendamento do procedimento na clínica veterinária</h3>
                                <p>Após receber a autorização, o tutor deve agendar a castração diretamente na Clínica Bichos e Cia.</p>
                                <div className={styles.step_info_line}>
                                    <FaMapMarkerAlt />
                                    <div><strong>Endereço:</strong> Avenida Dr. Labieno da Costa Machado, 5 – Garça/SP</div>
                                </div>
                                <div className={styles.step_info_line}>
                                    <FaClock />
                                    <div><strong>Horário de atendimento:</strong> conforme disponibilidade da clínica</div>
                                </div>
                            </div>

                        </div>

                        <div className={styles.final_cta}>
                            <p>Dúvidas? Entre em contato com a SAMA ou SEMADS.</p>
                        </div>

                    </div>

                </div>
            </div>
        </section>
    )
}

export default Castracao
