import api from '../../../utils/api'
import { getApiBase } from '../../../utils/api'

import { useState, useEffect } from 'react'
import { useParams, Link, useHistory } from 'react-router-dom'
import { FaCheckCircle, FaExclamationTriangle } from 'react-icons/fa'

import styles from './PetDetails.module.css'

/* hooks */
import useFlashMessage from '../../../hooks/useFlashMessage'

function PetDetails() {
    const [pet, setPet] = useState({})
    const { id } = useParams()
    const { setFlashMessage } = useFlashMessage()
    const [token] = useState(localStorage.getItem('token') || '')
    const [showAddressForm, setShowAddressForm] = useState(false)
    const [address, setAddress] = useState('')
    const history = useHistory()

    useEffect(() => {
        if (id) {
            api.get(`/pets/${id}`)
                .then((response) => {
                    setPet(response.data.pet)
                })
                .catch((error) => {
                    setFlashMessage(
                        error.response?.data?.message || 'Erro ao carregar pet',
                        'error'
                    )
                })
        }
    }, [id]) // eslint-disable-line react-hooks/exhaustive-deps

    function handleAdoptClick() {
        setShowAddressForm(true)
    }

    async function scheduleVisit() {
        if (!address.trim()) {
            setFlashMessage('Por favor, informe o endereço de entrega', 'error')
            return
        }

        let msgType = 'success'

        const data = await api
            .patch(`/pets/schedule/${pet._id}`, {
                deliveryAddress: address.trim()
            }, {
                headers: {
                    Authorization: `Bearer ${JSON.parse(token)}`
                }
            })
            .then((response) => {
                return response.data
            })
            .catch((err) => {
                msgType = 'error'
                return err.response?.data || { message: 'Erro ao solicitar adoção. Tente novamente.' }
            })

        if (msgType === 'success') {
            const successMessage = `Solicitação enviada com sucesso. O doador ${pet.user.name} foi notificado. Entre em contato pelo telefone ${pet.user.phone} para combinar os detalhes da entrega.`
            setFlashMessage(successMessage, msgType)
            setShowAddressForm(false)
            setAddress('')

            // Redirecionar para a página home de pets após 2 segundos
            setTimeout(() => {
                history.push('/')
            }, 2000)
        } else {
            setFlashMessage(data.message, msgType)
        }
    }

    return (
        <>
            {pet.name && (
                <section className={styles.pet_details_container}>
                    <div className={styles.pet_details_header}>
                        <h1>Conhecendo o Pet: {pet.name}</h1>
                        <p>Se tiver interesse, solicite a adoção deste pet</p>
                    </div>

                    <div className={styles.pet_images}>
                        {pet.images &&
                            pet.images.length > 0 &&
                            pet.images.map((image, index) => (
                                <img
                                    src={`${getApiBase()}/images/pets/${image}`}
                                    alt={pet.name}
                                    key={index}
                                />
                            ))}
                    </div>

                    <div className={styles.pet_info_section}>
                        <p>
                            <span className="bold">Peso:</span> {pet.weight}kg
                        </p>

                        <p>
                            <span className="bold">Idade:</span> {String(pet.age).match(/(mes|mês|ano)/i) ? pet.age : `${pet.age} anos`}
                        </p>

                        {pet.gender && (
                            <p>
                                <span className="bold">Gênero:</span> {pet.gender}
                            </p>
                        )}

                        {pet.color && (
                            <p>
                                <span className="bold">Cor:</span> {pet.color}
                            </p>
                        )}

                        {pet.user && (
                            <>
                                <p>
                                    <span className="bold">Doador:</span> {pet.user.name}
                                </p>
                                {pet.user.phone && (
                                    <p>
                                        <span className="bold">Telefone:</span> {pet.user.phone}
                                    </p>
                                )}
                            </>
                        )}
                    </div>

                    {token ? (
                        pet.available ? (
                            pet.adopter && pet.adopter._id ? (
                                <div className={styles.status_message}>
                                    <FaCheckCircle className={styles.status_icon} />
                                    <div>
                                        <h3>✓ Você já solicitou a adoção deste pet!</h3>
                                        <p>Entre em contato com {pet.user.name} pelo telefone: <strong>{pet.user.phone}</strong></p>
                                        <p className={styles.status_note}>Acompanhe sua solicitação em "Minhas Adoções"</p>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    {!showAddressForm ? (
                                        <button onClick={handleAdoptClick} className={styles.action_button}>
                                            Solicitar Adoção
                                        </button>
                                    ) : (
                                        <div className={styles.address_form_container}>
                                            <div className={styles.form_header}>
                                                <span className={styles.form_icon}>📍</span>
                                                <h3>Informe o Endereço de Entrega</h3>
                                                <p>Informe o endereço completo onde deseja receber o pet</p>
                                            </div>
                                            <textarea
                                                value={address}
                                                onChange={(e) => setAddress(e.target.value)}
                                                placeholder="Exemplo: Rua das Flores, 123, Bairro Centro, Cidade - Estado, CEP 12345-678"
                                                className={styles.address_textarea}
                                            />
                                            <div className={styles.form_buttons}>
                                                <button
                                                    onClick={scheduleVisit}
                                                    className={styles.submit_button}
                                                >
                                                    Enviar Solicitação
                                                </button>
                                                <button
                                                    onClick={() => {
                                                        setShowAddressForm(false)
                                                        setAddress('')
                                                    }}
                                                    className={styles.cancel_button}
                                                >
                                                    Cancelar
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </>
                            )
                        ) : (
                            <div className={styles.status_message}>
                                <FaExclamationTriangle className={styles.status_icon} />
                                <div>
                                    <h3>Pet já foi adotado</h3>
                                    <p>Este pet não está mais disponível para adoção.</p>
                                </div>
                            </div>
                        )
                    ) : (
                        <div className={styles.login_prompt}>
                            <p>
                                Você precisa <Link to="/register">criar uma conta</Link> para solicitar a adoção
                            </p>
                        </div>
                    )}
                </section>
            )}
        </>
    )
}

export default PetDetails
